// DUEL 24 ZONES — deterministic, host-authoritative duel engine.
// All state is plain JSON so it can be mirrored to online guests.

import { CARDS, DECK_RECIPE, EXTRA_RECIPE } from './cards.js'

export const MAX_LP = 8000
export const ZONES = 5

let UID = 1
const nextUid = () => `u${UID++}`

function makeInst(id) {
  return {
    uid: nextUid(),
    id,
    faceDown: false,
    pos: 'atk',
    hasAttacked: false,
    atkBonus: 0,
    setTurn: 0,
    equippedUid: null,
  }
}

function shuffle(list) {
  const a = list.slice()
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1))
    ;[a[i], a[j]] = [a[j], a[i]]
  }
  return a
}

export const memo = (id) => CARDS[id]

export function addLog(st, text, tone = 'system') {
  st.log.push({ turn: st.turn, text, tone })
  if (st.log.length > 80) st.log.splice(0, st.log.length - 80)
}

export function fieldBuff(st, side) {
  const f = st.players[side].field
  if (!f) return 0
  const c = CARDS[f.id]
  return c.effect && c.effect.kind === 'field' ? c.effect.amount : 0
}

export function atkOf(st, side, inst) {
  if (!inst) return 0
  return Math.max(0, (CARDS[inst.id].atk || 0) + (inst.atkBonus || 0) + fieldBuff(st, side))
}

export function defOf(st, side, inst) {
  if (!inst) return 0
  return Math.max(0, (CARDS[inst.id].def || 0) + (inst.atkBonus || 0) + fieldBuff(st, side))
}

export function countMonsters(p) {
  let n = 0
  for (const z of p.monsters) if (z) n++
  if (p.emz) n++
  return n
}

export function zoneMonster(p, kind, index) {
  if (kind === 'emz') return p.emz
  if (kind === 'monster') return p.monsters[index] || null
  return null
}

export function setZoneMonster(p, kind, index, inst) {
  if (kind === 'emz') p.emz = inst
  else p.monsters[index] = inst
}

export function clearZoneMonster(p, kind, index) {
  if (kind === 'emz') p.emz = null
  else p.monsters[index] = null
}

export function firstFreeMonsterZone(p) {
  return p.monsters.findIndex((z) => !z)
}

export function firstFreeSpellZone(p) {
  return p.spells.findIndex((z) => !z)
}

export function strongestMonster(st, side) {
  const p = st.players[side]
  let best = null
  p.monsters.forEach((inst, index) => {
    if (!inst) return
    const val = atkOf(st, side, inst)
    if (!best || val > best.atk) best = { kind: 'monster', index, inst, atk: val, def: defOf(st, side, inst) }
  })
  if (p.emz) {
    const val = atkOf(st, side, p.emz)
    if (!best || val > best.atk) best = { kind: 'emz', index: 0, inst: p.emz, atk: val, def: defOf(st, side, p.emz) }
  }
  return best
}

export function attackersOf(st, side) {
  const p = st.players[side]
  const out = []
  p.monsters.forEach((inst, index) => {
    if (inst && !inst.faceDown && inst.pos === 'atk' && !inst.hasAttacked) {
      out.push({ kind: 'monster', index, inst })
    }
  })
  if (p.emz && !p.emz.faceDown && p.emz.pos === 'atk' && !p.emz.hasAttacked) {
    out.push({ kind: 'emz', index: 0, inst: p.emz })
  }
  return out
}

/* ───────────────────────────── SETUP ───────────────────────────── */

export function createDuel(names, starter = 0, opts = {}) {
  const players = names.map((name, i) => ({
    name,
    isCPU: i === 1 ? !!opts.cpuOpponent : false,
    lp: MAX_LP,
    deck: [],
    extra: [],
    hand: [],
    gy: [],
    banished: [],
    monsters: Array(ZONES).fill(null),
    spells: Array(ZONES).fill(null),
    field: null,
    emz: null,
    hasSummoned: false,
    extraUsed: false,
    lpLost: 0,
  }))

  players.forEach((p) => {
    p.deck = shuffle(DECK_RECIPE)
    p.extra = shuffle(EXTRA_RECIPE)
    for (let i = 0; i < 5; i++) p.hand.push(makeInst(p.deck.pop()))
  })

  const st = {
    v: 2,
    mode: opts.mode || 'cpu',
    turn: 1,
    active: starter,
    phase: 'main',
    winner: null,
    winReason: '',
    noAttacks: false,
    rev: 0,
    log: [],
    players,
    startedAt: Date.now(),
  }

  addLog(st, `DUEL START — ${names[starter]} が先攻`, 'system')
  addLog(st, '24ゾーン展開完了。カードは常に動き続ける。', 'system')
  return st
}

/* ─────────────────────────── PRIMITIVES ─────────────────────────── */

function damage(st, side, amount, ev) {
  if (st.winner) return
  amount = Math.max(0, Math.round(amount))
  if (!amount) return
  const p = st.players[side]
  p.lp = Math.max(0, p.lp - amount)
  p.lpLost = (p.lpLost || 0) + amount
  ev.push({ type: 'damage', side, amount, lp: p.lp, cardId: null })
  addLog(st, `${p.name} に ${amount} ダメージ（LP ${p.lp}）`, side === 0 ? 'p0' : 'p1')
  if (p.lp <= 0) endDuel(st, 1 - side, 'LPが0になった', ev)
}

function heal(st, side, amount, ev) {
  const p = st.players[side]
  const before = p.lp
  p.lp = Math.min(MAX_LP, p.lp + amount)
  const gained = p.lp - before
  ev.push({ type: 'heal', side, amount: gained, lp: p.lp })
  if (gained) addLog(st, `${p.name} は ${gained} LP回復（LP ${p.lp}）`, side === 0 ? 'p0' : 'p1')
}

function drawCards(st, side, amount, ev) {
  const p = st.players[side]
  for (let i = 0; i < amount; i++) {
    if (!p.deck.length) {
      ev.push({ type: 'deckout', side })
      addLog(st, `${p.name} のデッキが尽きた`, 'system')
      endDuel(st, 1 - side, 'デッキ切れ', ev)
      return
    }
    const inst = makeInst(p.deck.pop())
    p.hand.push(inst)
    ev.push({ type: 'draw', side, uid: inst.uid, cardId: inst.id })
  }
}

function endDuel(st, winner, reason, ev) {
  if (st.winner != null) return
  st.winner = winner
  st.winReason = reason
  ev.push({ type: 'result', winner, reason })
  addLog(st, `DUEL終了 — ${st.players[winner].name} の勝利（${reason}）`, 'system')
}

function removeEquipFor(st, side, uid, ev) {
  const p = st.players[side]
  p.spells.forEach((s, i) => {
    if (s && s.equippedUid === uid) {
      p.spells[i] = null
      p.gy.push(s)
      ev.push({ type: 'equipLost', side, zone: i, uid: s.uid, cardId: s.id })
    }
  })
}

export function destroyAt(st, side, kind, index, ev) {
  const p = st.players[side]
  const inst = zoneMonster(p, kind, index)
  if (!inst) return null
  clearZoneMonster(p, kind, index)
  const wasFaceDown = inst.faceDown
  inst.faceDown = false
  removeEquipFor(st, side, inst.uid, ev)
  p.gy.push(inst)
  ev.push({
    type: 'destroy', side, kind, index,
    uid: inst.uid, cardId: inst.id, faceDown: wasFaceDown,
  })
  addLog(st, `${p.name} の ${CARDS[inst.id].name} が破壊された`, side === 0 ? 'p0' : 'p1')
  return inst
}

/* ─────────────────────────── TRAP WINDOWS ─────────────────────────── */

function trapReady(st, inst) {
  return !!(inst && inst.faceDown && inst.setTurn < st.turn)
}

function triggerSummonTraps(st, defenderSide, targetSide, kind, index, inst, ev) {
  if (CARDS[inst.id].atk < 1500) return false
  const p = st.players[defenderSide]
  for (let i = 0; i < ZONES; i++) {
    const trap = p.spells[i]
    if (!trapReady(st, trap)) continue
    const c = CARDS[trap.id]
    if (c.type !== 'trap' || c.trigger !== 'summon') continue
    p.spells[i] = null
    p.gy.push(trap)
    ev.push({ type: 'trap', side: defenderSide, zone: i, cardId: trap.id, effect: 'destroySummoned', targetUid: inst.uid })
    addLog(st, `${p.name} は ${c.name} を発動！ ${CARDS[inst.id].name} を破壊`, defenderSide === 0 ? 'p0' : 'p1')
    destroyAt(st, targetSide, kind, index, ev)
    return true
  }
  return false
}

function triggerBattleTraps(st, defenderSide, ev) {
  const p = st.players[defenderSide]
  for (let i = 0; i < ZONES; i++) {
    const trap = p.spells[i]
    if (!trapReady(st, trap)) continue
    const c = CARDS[trap.id]
    if (c.type !== 'trap' || c.trigger !== 'battle') continue
    p.spells[i] = null
    p.gy.push(trap)
    st.noAttacks = true
    ev.push({ type: 'trap', side: defenderSide, zone: i, cardId: trap.id, effect: 'lockAttacks' })
    addLog(st, `${p.name} は ${c.name} を発動！ このターンの攻撃を封じた`, defenderSide === 0 ? 'p0' : 'p1')
    return true
  }
  return false
}

// returns true when the attack is negated
function triggerAttackTraps(st, defenderSide, attackerSide, ev) {
  const p = st.players[defenderSide]
  for (let i = 0; i < ZONES; i++) {
    const trap = p.spells[i]
    if (!trapReady(st, trap)) continue
    const c = CARDS[trap.id]
    if (c.type !== 'trap' || c.trigger !== 'attack') continue
    p.spells[i] = null
    p.gy.push(trap)
    ev.push({ type: 'trap', side: defenderSide, zone: i, cardId: trap.id, effect: 'negateAttack' })
    addLog(st, `${p.name} は ${c.name} を発動！ 攻撃を無効化`, defenderSide === 0 ? 'p0' : 'p1')
    damage(st, attackerSide, c.effect.amount || 0, ev)
    return true
  }
  for (let i = 0; i < ZONES; i++) {
    const trap = p.spells[i]
    if (!trapReady(st, trap)) continue
    const c = CARDS[trap.id]
    if (c.type !== 'trap' || c.trigger !== 'attacked') continue
    p.spells[i] = null
    p.gy.push(trap)
    ev.push({ type: 'trap', side: defenderSide, zone: i, cardId: trap.id, effect: 'draw' })
    addLog(st, `${p.name} は ${c.name} を発動！ 1枚ドロー`, defenderSide === 0 ? 'p0' : 'p1')
    drawCards(st, defenderSide, c.effect.amount || 1, ev)
    break
  }
  return false
}

/* ─────────────────────────── SUMMONING ─────────────────────────── */

function onSummonEffect(st, side, inst, ev) {
  if (st.winner) return
  const c = CARDS[inst.id]
  if (!c.onSummon) return
  const foe = 1 - side
  if (c.onSummon.kind === 'burn') {
    addLog(st, `${c.name} の召喚効果が発動`, side === 0 ? 'p0' : 'p1')
    damage(st, foe, c.onSummon.amount, ev)
  } else if (c.onSummon.kind === 'draw') {
    drawCards(st, side, c.onSummon.amount, ev)
  } else if (c.onSummon.kind === 'destroyEnemy') {
    const target = strongestMonster(st, foe)
    if (target) {
      addLog(st, `${c.name} の召喚効果で ${CARDS[target.inst.id].name} を破壊`, side === 0 ? 'p0' : 'p1')
      destroyAt(st, foe, target.kind, target.index, ev)
    }
  }
}

function summonMonster(st, side, handUid, zone, faceDown, ev) {
  const p = st.players[side]
  const idx = p.hand.findIndex((c) => c.uid === handUid)
  if (idx < 0) return 'そのカードは手札にない'
  const inst = p.hand[idx]
  const c = CARDS[inst.id]
  if (c.type !== 'monster') return 'モンスターではない'
  if (c.extra) return 'EXモンスターは特殊召喚専用'
  if (p.hasSummoned) return 'このターンは既に召喚済み'
  if (zone < 0 || zone >= ZONES) return 'ゾーン指定が不正'
  if (p.monsters[zone]) return 'そのゾーンは埋まっている'

  p.hand.splice(idx, 1)
  inst.faceDown = !!faceDown
  inst.pos = faceDown ? 'def' : 'atk'
  inst.hasAttacked = false
  inst.setTurn = st.turn
  p.monsters[zone] = inst
  p.hasSummoned = true
  ev.push({
    type: faceDown ? 'setMonster' : 'summon',
    side, zoneKind: 'monster', index: zone,
    uid: inst.uid, cardId: inst.id, faceDown: !!faceDown,
  })
  addLog(st, `${p.name} は ${faceDown ? 'モンスターをセット' : `${c.name} を召喚`}`, side === 0 ? 'p0' : 'p1')

  const destroyed = triggerSummonTraps(st, 1 - side, side, 'monster', zone, inst, ev)
  if (!destroyed && !faceDown) onSummonEffect(st, side, inst, ev)
  return null
}

function specialSummonExtra(st, side, cardId, ev) {
  const p = st.players[side]
  if (countMonsters(p) < 2) return 'モンスターが2体以上必要'
  if (p.emz) return 'EXゾーンが埋まっている'
  if (p.extraUsed) return 'このターンは既にEX召喚済み'
  const idx = p.extra.indexOf(cardId)
  if (idx < 0) return 'EXデッキにそのカードはない'
  p.extra.splice(idx, 1)
  const inst = makeInst(cardId)
  inst.setTurn = st.turn
  p.emz = inst
  p.extraUsed = true
  ev.push({ type: 'special', side, zoneKind: 'emz', index: 0, uid: inst.uid, cardId, from: 'extra' })
  addLog(st, `${p.name} は ${CARDS[cardId].name} をEXゾーンに特殊召喚！`, side === 0 ? 'p0' : 'p1')
  triggerSummonTraps(st, 1 - side, side, 'emz', 0, inst, ev)
  return null
}

function reviveMonster(st, side, ev) {
  const p = st.players[side]
  if (p.emz) return 'EXゾーンが埋まっている'
  const candidates = p.gy.filter((c) => {
    const cd = CARDS[c.id]
    return cd.type === 'monster' && !cd.extra
  })
  if (!candidates.length) return '墓地にモンスターがいない'
  candidates.sort((a, b) => atkOf(st, side, b) - atkOf(st, side, a))
  const inst = candidates[0]
  p.gy.splice(p.gy.indexOf(inst), 1)
  inst.faceDown = false
  inst.pos = 'atk'
  inst.hasAttacked = false
  inst.atkBonus = inst.atkBonus || 0
  inst.equippedUid = null
  p.emz = inst
  ev.push({ type: 'special', side, zoneKind: 'emz', index: 0, uid: inst.uid, cardId: inst.id, from: 'gy' })
  addLog(st, `${p.name} は ${CARDS[inst.id].name} をEXゾーンに蘇生！`, side === 0 ? 'p0' : 'p1')
  triggerSummonTraps(st, 1 - side, side, 'emz', 0, inst, ev)
}

/* ─────────────────────────── SPELLS ─────────────────────────── */

function resolveSpellEffect(st, side, inst, ev) {
  const c = CARDS[inst.id]
  if (!c.effect) return
  const foe = 1 - side
  const p = st.players[side]
  switch (c.effect.kind) {
    case 'draw':
      drawCards(st, side, c.effect.amount, ev)
      break
    case 'burn':
      damage(st, foe, c.effect.amount, ev)
      break
    case 'heal':
      heal(st, side, c.effect.amount, ev)
      break
    case 'destroy': {
      const target = strongestMonster(st, foe)
      if (target) {
        addLog(st, `${c.name} で ${CARDS[target.inst.id].name} を破壊`, side === 0 ? 'p0' : 'p1')
        destroyAt(st, foe, target.kind, target.index, ev)
      } else {
        addLog(st, `${c.name} は対象がいなかった`, side === 0 ? 'p0' : 'p1')
      }
      break
    }
    case 'revive': {
      const err = reviveMonster(st, side, ev)
      if (err) addLog(st, `${c.name} は不発に終わった（${err}）`, side === 0 ? 'p0' : 'p1')
      break
    }
    case 'field': {
      if (p.field) {
        p.gy.push(p.field)
        ev.push({ type: 'fieldLost', side, uid: p.field.uid, cardId: p.field.id })
      }
      p.field = inst
      inst.faceDown = false
      inst.setTurn = st.turn
      ev.push({ type: 'field', side, uid: inst.uid, cardId: inst.id })
      addLog(st, `${p.name} はフィールド魔法 ${c.name} を発動`, side === 0 ? 'p0' : 'p1')
      break
    }
    default:
      break
  }
}

function spellIsUsable(st, side, inst) {
  const c = CARDS[inst.id]
  const p = st.players[side]
  if (c.effect.kind === 'equip') return countMonsters(p) > 0 && firstFreeSpellZone(p) >= 0
  if (c.effect.kind === 'revive') return !p.emz && p.gy.some((g) => {
    const cd = CARDS[g.id]
    return cd.type === 'monster' && !cd.extra
  })
  return true
}

function activateSpellFromHand(st, side, handUid, spellZone, ev) {
  const p = st.players[side]
  const idx = p.hand.findIndex((c) => c.uid === handUid)
  if (idx < 0) return 'そのカードは手札にない'
  const inst = p.hand[idx]
  const c = CARDS[inst.id]
  if (c.type !== 'spell') return '魔法カードではない'
  if (!spellIsUsable(st, side, inst)) return '発動条件を満たしていない'

  p.hand.splice(idx, 1)
  if (c.effect.kind === 'equip') {
    if (spellZone < 0 || p.spells[spellZone]) return '魔法ゾーンが空いていない'
    const target = strongestMonster(st, side)
    if (!target) return '装備対象がいない'
    inst.faceDown = false
    inst.equippedUid = target.inst.uid
    inst.setTurn = st.turn
    p.spells[spellZone] = inst
    target.inst.atkBonus = (target.inst.atkBonus || 0) + c.effect.amount
    ev.push({ type: 'spell', side, cardId: inst.id, effect: 'equip', targetUid: target.inst.uid, atk: c.effect.amount })
    addLog(st, `${p.name} は ${c.name} を ${CARDS[target.inst.id].name} に装備（ATK+${c.effect.amount}）`, side === 0 ? 'p0' : 'p1')
    return null
  }

  if (c.effect.kind === 'field') {
    resolveSpellEffect(st, side, inst, ev)
    return null
  }

  ev.push({ type: 'spell', side, cardId: inst.id, effect: c.effect.kind })
  addLog(st, `${p.name} は魔法カード ${c.name} を発動`, side === 0 ? 'p0' : 'p1')
  resolveSpellEffect(st, side, inst, ev)
  p.gy.push(inst)
  return null
}

function activateSetSpell(st, side, zone, ev) {
  const p = st.players[side]
  const inst = p.spells[zone]
  if (!inst || !inst.faceDown) return 'セットされた魔法カードがない'
  if (inst.setTurn >= st.turn) return 'セットしたターンには発動できない'
  const c = CARDS[inst.id]
  if (c.type !== 'spell') return '魔法カードではない'
  if (!spellIsUsable(st, side, inst)) return '発動条件を満たしていない'

  if (c.effect.kind === 'equip') {
    const target = strongestMonster(st, side)
    if (!target) return '装備対象がいない'
    inst.faceDown = false
    inst.equippedUid = target.inst.uid
    target.inst.atkBonus = (target.inst.atkBonus || 0) + c.effect.amount
    ev.push({ type: 'spell', side, cardId: inst.id, effect: 'equip', targetUid: target.inst.uid, atk: c.effect.amount })
    addLog(st, `${p.name} はセットした ${c.name} を発動`, side === 0 ? 'p0' : 'p1')
    return null
  }

  p.spells[zone] = null
  inst.faceDown = false
  ev.push({ type: 'spell', side, cardId: inst.id, effect: c.effect.kind })
  addLog(st, `${p.name} はセットした ${c.name} を発動`, side === 0 ? 'p0' : 'p1')
  if (c.effect.kind === 'field') {
    resolveSpellEffect(st, side, inst, ev)
  } else {
    resolveSpellEffect(st, side, inst, ev)
    p.gy.push(inst)
  }
  return null
}

/* ─────────────────────────── ATTACKS ─────────────────────────── */

function resolveAttack(st, side, action, ev) {
  const p = st.players[side]
  const foe = 1 - side
  const o = st.players[foe]
  const attacker = zoneMonster(p, action.zoneKind, action.zoneIndex)
  if (!attacker) return '攻撃するモンスターがいない'
  if (attacker.faceDown || attacker.pos !== 'atk') return '攻撃表示のモンスターではない'
  if (attacker.hasAttacked) return 'そのモンスターは既に攻撃した'
  if (st.phase !== 'battle') return 'バトルフェイズではない'
  if (st.noAttacks) return 'このターンは攻撃できない'

  const direct = action.targetKind === 'direct'
  const oppHas = countMonsters(o) > 0
  const attackerCard = CARDS[attacker.id]
  if (direct) {
    if (oppHas && !attackerCard.direct) return '相手モンスターが存在する'
  } else {
    if (!oppHas) return '相手モンスターがいない（直接攻撃）'
    const target = zoneMonster(o, action.targetKind, action.targetIndex)
    if (!target) return '攻撃対象がいない'
  }

  attacker.hasAttacked = true
  const atk = atkOf(st, side, attacker)
  const from = { kind: action.zoneKind, index: action.zoneIndex, uid: attacker.uid, cardId: attacker.id, atk }
  if (direct) {
    ev.push({ type: 'attack', side, from, to: null, direct: true, atk, damage: atk })
    addLog(st, `${p.name} の ${attackerCard.name} が直接攻撃！（${atk}）`, side === 0 ? 'p0' : 'p1')
    const negated = triggerAttackTraps(st, foe, side, ev)
    if (!negated) damage(st, foe, atk, ev)
    return null
  }

  const target = zoneMonster(o, action.targetKind, action.targetIndex)
  const targetCard = CARDS[target.id]
  const wasFaceDown = target.faceDown
  const targetPos = target.faceDown ? 'def' : target.pos
  target.faceDown = false
  ev.push({
    type: 'attack', side, from,
    to: { kind: action.targetKind, index: action.targetIndex, uid: target.uid, cardId: target.id, faceDown: wasFaceDown },
    direct: false, atk, targetPos,
  })
  addLog(st, `${p.name} の ${attackerCard.name} が ${targetCard.name} に攻撃`, side === 0 ? 'p0' : 'p1')
  const negated = triggerAttackTraps(st, foe, side, ev)
  if (negated) return null

  if (targetPos === 'def') {
    const def = defOf(st, foe, target)
    if (atk > def) {
      destroyAt(st, foe, action.targetKind, action.targetIndex, ev)
    } else if (atk < def) {
      damage(st, side, def - atk, ev)
    } else {
      addLog(st, '攻撃は弾かれた', 'system')
    }
  } else {
    const targetAtk = atkOf(st, foe, target)
    if (atk > targetAtk) {
      destroyAt(st, foe, action.targetKind, action.targetIndex, ev)
    } else if (atk < targetAtk) {
      damage(st, side, targetAtk - atk, ev)
      destroyAt(st, side, action.zoneKind, action.zoneIndex, ev)
    } else {
      destroyAt(st, foe, action.targetKind, action.targetIndex, ev)
      destroyAt(st, side, action.zoneKind, action.zoneIndex, ev)
      addLog(st, '相打ち！ 双方のモンスターが消滅', 'system')
    }
  }
  return null
}

/* ─────────────────────────── MAIN ENTRY ─────────────────────────── */

export function applyAction(st, side, action) {
  const ev = []
  if (!st || st.winner != null) return { ok: false, error: 'デュエルは終了している', events: ev }
  if (!action || !action.type) return { ok: false, error: '不正な操作', events: ev }
  if (side !== st.active) return { ok: false, error: '相手のターン中です', events: ev }
  const p = st.players[side]
  const o = st.players[1 - side]
  let error = null

  switch (action.type) {
    case 'summon':
      error = summonMonster(st, side, action.handUid, Number(action.zone), false, ev)
      break
    case 'setMonster':
      error = summonMonster(st, side, action.handUid, Number(action.zone), true, ev)
      break
    case 'activateSpell': {
      if (st.phase !== 'main') { error = 'メインフェイズではない'; break }
      error = activateSpellFromHand(st, side, action.handUid, Number(action.zone ?? firstFreeSpellZone(p)), ev)
      break
    }
    case 'setSpell': {
      if (st.phase !== 'main') { error = 'メインフェイズではない'; break }
      const idx = p.hand.findIndex((c) => c.uid === action.handUid)
      if (idx < 0) { error = 'そのカードは手札にない'; break }
      const card = CARDS[p.hand[idx].id]
      if (card.type !== 'spell' && card.type !== 'trap') { error = '魔法・罠カードではない'; break }
      const zone = Number(action.zone)
      if (zone < 0 || zone >= ZONES || p.spells[zone]) { error = '魔法・罠ゾーンが空いていない'; break }
      if (!p.spells.some((s) => !s)) { error = '魔法・罠ゾーンが空いていない'; break }
      const inst = p.hand.splice(idx, 1)[0]
      inst.faceDown = true
      inst.setTurn = st.turn
      p.spells[zone] = inst
      ev.push({ type: 'setSpell', side, zone, uid: inst.uid, cardId: inst.id, cardType: card.type })
      addLog(st, `${p.name} は ${card.name} をセット`, side === 0 ? 'p0' : 'p1')
      break
    }
    case 'activateSet': {
      if (st.phase !== 'main') { error = 'メインフェイズではない'; break }
      error = activateSetSpell(st, side, Number(action.zone), ev)
      break
    }
    case 'specialSummon': {
      if (st.phase !== 'main') { error = 'メインフェイズではない'; break }
      error = specialSummonExtra(st, side, action.cardId, ev)
      break
    }
    case 'toBattle': {
      if (st.phase !== 'main') { error = '既にバトルフェイズ'; break }
      st.phase = 'battle'
      ev.push({ type: 'phase', phase: 'battle', side })
      addLog(st, `${p.name} はバトルフェイズに移行`, side === 0 ? 'p0' : 'p1')
      triggerBattleTraps(st, 1 - side, ev)
      break
    }
    case 'attack': {
      if (st.phase !== 'battle') { error = 'バトルフェイズではない'; break }
      error = resolveAttack(st, side, action, ev)
      break
    }
    case 'endTurn': {
      if (st.winner != null) break
      p.hasSummoned = false
      o.hasSummoned = false
      p.extraUsed = false
      o.extraUsed = false
      st.active = 1 - side
      st.turn++
      st.phase = 'main'
      st.noAttacks = false
      st.players.forEach((pl) => {
        pl.monsters.forEach((m) => { if (m) m.hasAttacked = false })
        if (pl.emz) pl.emz.hasAttacked = false
      })
      ev.push({ type: 'turn', side: st.active, turn: st.turn })
      addLog(st, `── TURN ${st.turn} · ${st.players[st.active].name} ──`, 'system')
      drawCards(st, st.active, 1, ev)
      break
    }
    case 'surrender': {
      endDuel(st, 1 - side, '降参', ev)
      break
    }
    default:
      error = '不明な操作'
  }

  if (error) return { ok: false, error, events: [] }
  st.rev = (st.rev || 0) + 1
  return { ok: true, events: ev }
}

/* ─────────────────────────── CPU DUELIST ─────────────────────────── */

const effectKind = (inst) => (CARDS[inst.id].effect && CARDS[inst.id].effect.kind) || ''

export function aiChooseAction(st, side = 1) {
  if (!st || st.winner != null || st.active !== side) return null
  const p = st.players[side]
  const o = st.players[1 - side]
  const hand = p.hand
  const spells = hand.filter((c) => CARDS[c.id].type === 'spell')
  const traps = hand.filter((c) => CARDS[c.id].type === 'trap')
  const monsters = hand.filter((c) => CARDS[c.id].type === 'monster')
  const myCount = countMonsters(p)
  const oppCount = countMonsters(o)
  const oppBest = strongestMonster(st, 1 - side)
  const myBest = strongestMonster(st, side)

  if (st.phase === 'main') {
    /* field spell */
    if (!p.field) {
      const field = spells.find((c) => effectKind(c) === 'field')
      if (field) return { type: 'activateSpell', handUid: field.uid }
    }

    /* draw power */
    const drawSpell = spells.find((c) => effectKind(c) === 'draw')
    if (drawSpell && p.deck.length >= 2) return { type: 'activateSpell', handUid: drawSpell.uid }

    /* lethal burn */
    const burns = spells.filter((c) => effectKind(c) === 'burn')
    if (burns.length) {
      const sorted = burns.sort((a, b) => CARDS[b.id].effect.amount - CARDS[a.id].effect.amount)
      if (CARDS[sorted[0].id].effect.amount >= o.lp) {
        return { type: 'activateSpell', handUid: sorted[0].uid }
      }
    }

    /* destroy a threat */
    if (oppBest && oppBest.atk >= 2000) {
      const removal = spells.find((c) => effectKind(c) === 'destroy')
      if (removal) return { type: 'activateSpell', handUid: removal.uid }
    }

    /* heal when low */
    if (p.lp <= 2800) {
      const healSpell = spells.find((c) => effectKind(c) === 'heal')
      if (healSpell) return { type: 'activateSpell', handUid: healSpell.uid }
    }

    /* burn when it matters or the hand is clogged */
    if (burns.length && (o.lp <= 3000 || hand.length >= 6)) {
      const best = burns.sort((a, b) => CARDS[b.id].effect.amount - CARDS[a.id].effect.amount)[0]
      if (myCount > 0 || o.lp <= 3000) return { type: 'activateSpell', handUid: best.uid }
    }

    /* revive a fallen boss */
    if (!p.emz && p.gy.some((g) => CARDS[g.id].type === 'monster' && !CARDS[g.id].extra)) {
      const revive = spells.find((c) => effectKind(c) === 'revive')
      if (revive) return { type: 'activateSpell', handUid: revive.uid }
    }

    /* equip the biggest body */
    if (myBest && firstFreeSpellZone(p) >= 0) {
      const equip = spells.find((c) => effectKind(c) === 'equip')
      if (equip) return { type: 'activateSpell', handUid: equip.uid }
    }

    /* normal summon / set */
    const freeMonster = firstFreeMonsterZone(p)
    if (!p.hasSummoned && freeMonster >= 0 && monsters.length) {
      const byAtk = monsters.slice().sort((a, b) => CARDS[b.id].atk - CARDS[a.id].atk)
      const best = byAtk[0]
      const bestAtk = CARDS[best.id].atk
      if (myCount === 0 && oppBest && bestAtk < oppBest.atk && bestAtk < 1800) {
        const byDef = monsters.slice().sort((a, b) => CARDS[b.id].def - CARDS[a.id].def)
        const setter = byDef[0]
        return { type: 'setMonster', handUid: setter.uid, zone: freeMonster }
      }
      return { type: 'summon', handUid: best.uid, zone: freeMonster }
    }

    /* extra deck */
    if (myCount >= 2 && !p.emz && !p.extraUsed && p.extra.length) {
      const bestExtra = p.extra.slice().sort((a, b) => CARDS[b].atk - CARDS[a].atk)[0]
      return { type: 'specialSummon', cardId: bestExtra }
    }

    /* set traps, max two face-down */
    const setTraps = p.spells.filter((s) => s && CARDS[s.id].type === 'trap').length
    if (setTraps < 2 && traps.length && firstFreeSpellZone(p) >= 0) {
      return { type: 'setSpell', handUid: traps[0].uid, zone: firstFreeSpellZone(p) }
    }

    /* battle */
    if (attackersOf(st, side).length) return { type: 'toBattle' }
    return { type: 'endTurn' }
  }

  if (st.phase === 'battle') {
    if (st.noAttacks) return { type: 'endTurn' }
    const attackers = attackersOf(st, side)
    if (!attackers.length) return { type: 'endTurn' }
    attackers.sort((a, b) => atkOf(st, side, b.inst) - atkOf(st, side, a.inst))

    const enemies = []
    o.monsters.forEach((inst, index) => {
      if (inst) enemies.push({ kind: 'monster', index, inst })
    })
    if (o.emz) enemies.push({ kind: 'emz', index: 0, inst: o.emz })

    for (const at of attackers) {
      const aAtk = atkOf(st, side, at.inst)
      const card = CARDS[at.inst.id]
      if (!enemies.length) {
        return { type: 'attack', zoneKind: at.kind, zoneIndex: at.index, targetKind: 'direct', targetIndex: 0 }
      }
      const beatable = enemies
        .map((e) => {
          const eAtk = atkOf(st, 1 - side, e.inst)
          const eDef = defOf(st, 1 - side, e.inst)
          const defense = e.inst.faceDown || e.inst.pos === 'def'
          return { ...e, eAtk, eDef, defense }
        })
        .filter((e) => (e.defense ? aAtk > e.eDef : aAtk > e.eAtk))
        .sort((a, b) => (b.defense ? b.eDef : b.eAtk) - (a.defense ? a.eDef : a.eAtk))

      if (beatable.length) {
        const target = beatable[0]
        return {
          type: 'attack', zoneKind: at.kind, zoneIndex: at.index,
          targetKind: target.kind, targetIndex: target.index,
        }
      }
      if (card.direct) {
        return { type: 'attack', zoneKind: at.kind, zoneIndex: at.index, targetKind: 'direct', targetIndex: 0 }
      }
    }
    return { type: 'endTurn' }
  }
  return null
}

/* ─────────────────────────── UI HELPERS ─────────────────────────── */

export function canSpecialSummon(st, side) {
  const p = st.players[side]
  return countMonsters(p) >= 2 && !p.emz && !p.extraUsed && p.extra.length > 0
}

export function spellUsable(st, side, inst) {
  return spellIsUsable(st, side, inst)
}

export function canActivateSet(st, side, zone) {
  const p = st.players[side]
  const inst = p.spells[zone]
  if (!inst || !inst.faceDown) return false
  if (CARDS[inst.id].type !== 'spell') return false
  if (inst.setTurn >= st.turn) return false
  return spellIsUsable(st, side, inst)
}

// Cross-tab room registry and realtime transport.
// Rooms live in localStorage (shared instantaneously between tabs) and
// live messages travel over BroadcastChannel.

const ROOM_KEY = 'duel24.rooms.v3'
const CHANNEL_NAME = 'duel24.net.v3'
const STALE_MS = 45000

export function randomCode() {
  const chars = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'
  let out = ''
  for (let i = 0; i < 4; i++) out += chars[Math.floor(Math.random() * chars.length)]
  return out
}

export function randomName() {
  const n = Math.floor(1000 + Math.random() * 9000)
  return `DUELIST-${n}`
}

function readAll() {
  try {
    const raw = localStorage.getItem(ROOM_KEY)
    if (!raw) return {}
    const parsed = JSON.parse(raw)
    return parsed && typeof parsed === 'object' ? parsed : {}
  } catch {
    return {}
  }
}

function writeAll(rooms) {
  try {
    localStorage.setItem(ROOM_KEY, JSON.stringify(rooms))
  } catch {
    /* storage might be unavailable; rooms still work inside this tab */
  }
}

export class RoomNet {
  constructor({ clientId, name, onMessage, onRooms }) {
    this.clientId = clientId
    this.name = name
    this.onMessage = onMessage || (() => {})
    this.onRooms = onRooms || (() => {})
    this.ownRoomId = null
    this.channel = null
    this.heartbeatTimer = null
    this.lastSeen = {}
    try {
      this.channel = new BroadcastChannel(CHANNEL_NAME)
      this.channel.onmessage = (event) => {
        if (event.data) this.onMessage(event.data)
      }
    } catch {
      this.channel = null
    }
    window.addEventListener('storage', (event) => {
      if (event.key === ROOM_KEY) this.onRooms()
    })
    this.heartbeatTimer = setInterval(() => this.heartbeat(), 4000)
  }

  ensureOwnRoom() {
    const rooms = readAll()
    let room = this.ownRoomId ? rooms[this.ownRoomId] : null
    if (!room) {
      const id = `r${Math.random().toString(36).slice(2, 10)}`
      room = {
        id,
        code: randomCode(),
        hostId: this.clientId,
        hostName: this.name,
        guestId: null,
        guestName: null,
        mode: 'cpu',
        joinable: true,
        createdAt: Date.now(),
        updatedAt: Date.now(),
      }
      // prune truly abandoned rooms from earlier sessions
      for (const [key, value] of Object.entries(rooms)) {
        if (!value || Date.now() - (value.updatedAt || 0) > 120000) delete rooms[key]
      }
      rooms[id] = room
      writeAll(rooms)
      this.ownRoomId = id
      this.broadcast({ type: 'rooms' })
    } else {
      this.ownRoomId = room.id
      this.updateRoom(room.id, { hostName: this.name })
    }
    this.onRooms()
    return this.ownRoom()
  }

  ownRoom() {
    if (!this.ownRoomId) return null
    return readAll()[this.ownRoomId] || null
  }

  updateRoom(id, patch, broadcast = true) {
    const rooms = readAll()
    const room = rooms[id]
    if (!room) return null
    Object.assign(room, patch, { updatedAt: Date.now() })
    rooms[id] = room
    writeAll(rooms)
    if (broadcast) this.broadcast({ type: 'rooms' })
    this.onRooms()
    return room
  }

  setAway(away) {
    if (!this.ownRoomId) return
    this.updateRoom(this.ownRoomId, {
      mode: away ? 'away' : 'cpu',
      joinable: !away,
      guestId: null,
      guestName: null,
    })
  }

  removeRoom(id) {
    const rooms = readAll()
    if (!rooms[id]) return
    delete rooms[id]
    writeAll(rooms)
    this.broadcast({ type: 'rooms' })
    this.onRooms()
  }

  list() {
    const rooms = readAll()
    return Object.values(rooms)
      .filter((room) => room && room.id && room.hostId)
      .sort((a, b) => (b.createdAt || 0) - (a.createdAt || 0))
  }

  fresh(room, windowMs = STALE_MS) {
    return !!room && Date.now() - (room.updatedAt || 0) < windowMs
  }

  heartbeat() {
    if (!this.ownRoomId) return
    const rooms = readAll()
    const room = rooms[this.ownRoomId]
    if (!room) return
    room.updatedAt = Date.now()
    room.hostName = this.name
    writeAll(rooms)
    this.broadcast({ type: 'heartbeat', roomId: this.ownRoomId, from: this.clientId, name: this.name })
  }

  send(message) {
    if (!this.channel) return
    try {
      this.channel.postMessage(message)
    } catch {
      /* ignore */
    }
  }

  broadcast(message) {
    this.send(message)
  }

  destroy() {
    if (this.heartbeatTimer) clearInterval(this.heartbeatTimer)
    if (this.ownRoomId) this.removeRoom(this.ownRoomId)
    if (this.channel) {
      try { this.channel.close() } catch { /* ignore */ }
      this.channel = null
    }
  }
}

import { CARDS, ATTR_LABEL, RARITY_LABEL, cardTypeLabel } from './cards.js'
import {
  atkOf, defOf, countMonsters, attackersOf,
  canSpecialSummon, canActivateSet, spellUsable, zoneMonster, MAX_LP,
} from './engine.js'

export const $ = (sel, root = document) => root.querySelector(sel)
export const esc = (value) => String(value ?? '').replace(/[&<>"']/g, (ch) => ({
  '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;',
}[ch]))
export const fmt = (n) => Number(n || 0).toLocaleString('en-US')

export function modeLabel(app) {
  if (app.connecting) return '接続中'
  if (app.hostGone) return '切断'
  if (app.role === 'guest' || app.mode === 'online') return '対人戦'
  return 'CPU戦'
}

export function roomCodeFor(app) {
  if (app.role === 'guest' || app.role === 'guest-pending' || app.role === 'guest-left') {
    if (app.hostCode) return app.hostCode
    const room = app.net.list().find((r) => r.id === app.inRoomId)
    return room?.code || '----'
  }
  return app.net.ownRoom()?.code || '----'
}

function button(label, attrs, disabled = false, cls = '') {
  const data = Object.entries(attrs || {})
    .map(([key, value]) => `data-${key}="${esc(value)}"`)
    .join(' ')
  return `<button class="btn ${cls}" ${data}${disabled ? ' disabled' : ''}>${label}</button>`
}

/* ───────────────────────── CARD MARKUP ───────────────────────── */

export function cardHTML(app, inst, ctx = {}) {
  if (!inst) return ''
  const c = CARDS[inst.id]
  if (!c) return ''
  const idx = Number(ctx.index ?? 0)
  const delay = `--i:${idx};--seed:${(inst.uid || '').replace(/\D/g, '') % 9}`

  if (ctx.faceDown) {
    return `<div class="card card-back" data-uid="${esc(inst.uid)}" style="${delay}">
      <div class="back-lines"></div>
      <span class="back-mark">24</span>
      <span class="back-sub">DUEL</span>
      <span class="back-set">SET</span>
    </div>`
  }

  const side = ctx.side
  const st = app.state
  const isMonster = c.type === 'monster'
  const effAtk = isMonster && st && side != null ? atkOf(st, side, inst) : (c.atk || 0)
  const effDef = isMonster && st && side != null ? defOf(st, side, inst) : (c.def || 0)
  const buffed = isMonster && (effAtk !== (c.atk || 0) || effDef !== (c.def || 0))
  const tag = isMonster
    ? (c.extra ? 'EX' : `Lv.${c.level}`)
    : c.type === 'spell'
      ? (c.spellType === 'field' ? 'FIELD' : c.spellType === 'equip' ? 'EQUIP' : 'SPELL')
      : 'TRAP'

  const foot = isMonster
    ? `<span class="stat atk${buffed ? ' buffed' : ''}"><i>ATK</i><b>${fmt(effAtk)}</b></span>
       <span class="stat def${buffed ? ' buffed' : ''}"><i>DEF</i><b>${fmt(effDef)}</b></span>`
    : `<span class="spell-kind">${tag}</span><span class="spell-mark">${esc(ATTR_LABEL[c.attr])}</span>`

  const badges = []
  if (isMonster && ctx.side != null && inst.pos === 'def' && !inst.faceDown) {
    badges.push('<span class="pos-badge">DEF</span>')
  }
  if (isMonster && inst.atkBonus) badges.push(`<span class="buff-badge">+${inst.atkBonus}</span>`)
  if (c.extra) badges.push('<span class="extra-badge">EX</span>')

  return `<div class="card type-${c.type} attr-${c.attr} rarity-${c.rarity || 'n'}${c.extra ? ' is-extra' : ''}${inst.faceDown ? ' is-set' : ''}"
      data-uid="${esc(inst.uid)}" data-card-id="${esc(inst.id)}" style="${delay}">
    <div class="card-sheen"></div>
    <div class="card-head">
      <span class="card-name">${esc(c.name)}</span>
      <span class="card-tag">${tag}</span>
    </div>
    <div class="card-art">
      <span class="art-orbit"></span>
      <span class="art-glyph">${esc(c.glyph)}</span>
      <span class="art-attr" title="${esc(ATTR_LABEL[c.attr])}">${esc(ATTR_LABEL[c.attr])}</span>
    </div>
    <div class="card-foot">${foot}</div>
    ${badges.join('')}
  </div>`
}

export function cardRowHTML(app, inst, ctx = {}) {
  const c = CARDS[inst.id]
  if (!c) return ''
  const isMonster = c.type === 'monster'
  const stats = isMonster
    ? `<span class="row-stat">ATK ${fmt(c.atk)} / DEF ${fmt(c.def)}</span>`
    : `<span class="row-stat">${esc(cardTypeLabel(c))}</span>`
  return `<div class="card-row attr-${c.attr}">
    <span class="row-glyph">${esc(c.glyph)}</span>
    <div class="row-main">
      <div class="row-title"><b>${esc(c.name)}</b><span class="rarity rarity-${c.rarity || 'n'}">${RARITY_LABEL[c.rarity || 'n']}</span>${stats}</div>
      <p class="row-text">${esc(c.text || '')}</p>
    </div>
    ${ctx.action || ''}
  </div>`
}

/* ───────────────────────── TOP BAR ───────────────────────── */

export function renderTopbar(app) {
  const rooms = app.net.list()
  const joinable = rooms.filter((r) =>
    r.id !== app.ownRoomId && r.hostId !== app.clientId &&
    app.net.fresh(r) && r.joinable && r.mode !== 'pvp' && r.mode !== 'away').length
  const count = $('#roomCount')
  if (count) count.textContent = String(joinable)
  const roomText = $('#roomChipText')
  if (roomText) roomText.textContent = `ROOM ${roomCodeFor(app)}`
  const chipMode = $('#roomChipMode')
  if (chipMode) {
    chipMode.textContent = modeLabel(app)
    chipMode.className = `chip-mode mode-${app.connecting ? 'wait' : app.hostGone ? 'gone' : app.mode === 'online' ? 'pvp' : 'cpu'}`
  }
  const chip = $('#roomChip')
  if (chip) chip.dataset.online = String(app.mode === 'online')
  const sound = $('#soundBtn')
  if (sound) sound.textContent = app.soundOn ? 'SOUND ON' : 'SOUND OFF'
}

/* ───────────────────────── FIELD ───────────────────────── */

function zoneHTML(app, side, kind, index, zoneNumber) {
  const st = app.state
  const p = st.players[side]
  const inst = kind === 'monster' ? p.monsters[index] : kind === 'spell' ? p.spells[index] : kind === 'field' ? p.field : p.emz
  const mine = side === app.mySide
  const sel = app.sel
  const classes = ['zone', `zone-${kind}`, mine ? 'is-mine' : 'is-foe']
  let label = kind === 'monster' ? `M${index + 1}` : kind === 'spell' ? `S${index + 1}` : kind === 'field' ? 'FIELD' : 'EX'
  if (inst) classes.push('filled')

  if (sel?.kind === 'place' && mine && !inst) {
    const expected = sel.mode === 'setSpell' ? 'spell' : 'monster'
    if (kind === expected) classes.push('hl-place')
  }
  if (sel?.kind === 'attacker') {
    if (mine && sel.zoneKind === kind && (kind === 'emz' || sel.zoneIndex === index)) classes.push('hl-attacker')
    if (!mine && inst && (kind === 'monster' || kind === 'emz')) classes.push('hl-target')
  }
  if (st.phase === 'battle' && st.active === side && mine && !st.noAttacks && inst &&
      !inst.faceDown && inst.pos === 'atk' && !inst.hasAttacked) {
    classes.push('can-attack')
  }
  if (kind === 'emz' && mine && !inst && canSpecialSummon(st, side) && st.phase === 'main' && st.active === side) {
    classes.push('emz-ready')
  }
  if (sel?.kind === 'info' && sel.side === side && sel.zoneKind === kind && sel.zoneIndex === index) {
    classes.push('hl-info')
  }

  const faceDown = !!inst?.faceDown
  const content = inst
    ? cardHTML(app, inst, { side, kind, index, faceDown })
    : `<span class="zone-plus">${kind === 'emz' ? 'EX' : kind === 'field' ? 'FIELD' : '＋'}</span>`

  return `<div class="${classes.join(' ')}" data-act="zone" data-side="${side}" data-kind="${kind}" data-index="${index}"
      data-zone="${zoneNumber}" role="button" aria-label="${mine ? '自分' : '相手'}の${label}ゾーン">
    <span class="zone-num">${String(zoneNumber).padStart(2, '0')}</span>
    <span class="zone-label">${label}</span>
    ${content}
  </div>`
}

function pilesHTML(app, side) {
  const st = app.state
  const p = st.players[side]
  const mine = side === app.mySide
  const exReady = mine && canSpecialSummon(st, side)
  return `<div class="piles">
    <button class="pile pile-deck" data-act="openPile" data-side="${side}" data-pile="deck" aria-label="デッキ">
      <span class="pile-label">DECK</span><b>${p.deck.length}</b><i>山札</i>
    </button>
    <button class="pile pile-extra${exReady ? ' ready' : ''}" data-act="openPile" data-side="${side}" data-pile="extra" aria-label="EXデッキ">
      <span class="pile-label">EX</span><b>${p.extra.length}</b><i>${exReady ? 'READY' : 'EXデッキ'}</i>
    </button>
    <button class="pile pile-gy" data-act="openPile" data-side="${side}" data-pile="gy" aria-label="墓地">
      <span class="pile-label">GY</span><b>${p.gy.length}</b><i>墓地</i>
    </button>
    <button class="pile pile-void" data-act="openPile" data-side="${side}" data-pile="banished" aria-label="除外">
      <span class="pile-label">VOID</span><b>${p.banished.length}</b><i>除外</i>
    </button>
  </div>`
}

function playerBarHTML(app, side, who) {
  const st = app.state
  const p = st.players[side]
  const mine = side === app.mySide
  const active = st.active === side
  const lpPct = Math.max(0, Math.min(100, (p.lp / MAX_LP) * 100))
  const low = p.lp <= 3000
  const glyph = Array.from(p.name || 'DUEL')[0] || 'D'
  const rival = !mine
  const badges = []
  if (mine) badges.push('<span class="p-badge you">YOU</span>')
  if (rival && p.isCPU) badges.push('<span class="p-badge cpu">CPU</span>')
  if (rival && !p.isCPU) badges.push('<span class="p-badge rival">RIVAL</span>')
  if (active && st.winner == null) badges.push('<span class="p-badge active">ACTIVE</span>')
  if (p.extraUsed) badges.push('<span class="p-badge ex">EX USED</span>')

  const handStack = rival
    ? `<div class="hand-stack" aria-label="相手の手札 ${p.hand.length}枚">
        ${Array.from({ length: Math.min(5, p.hand.length) }).map((_, i) => `<span class="mini-back" style="--i:${i}"></span>`).join('')}
        <b>${p.hand.length}</b>
      </div>`
    : `<div class="hand-stack self-hand"><b>${p.hand.length}</b><span>手札</span></div>`

  return `<div class="player-bar ${who} ${active ? 'is-active' : ''}">
    <div class="avatar ${low ? 'low' : ''}"><span>${esc(glyph)}</span><i class="avatar-ring"></i></div>
    <div class="p-main">
      <div class="p-name-row">
        <span class="p-name">${esc(p.name)}</span>
        ${badges.join('')}
      </div>
      <div class="lp-block" data-lp-side="${side}">
        <div class="lp-top"><span class="lp-label">LIFE POINT</span><span class="lp-num ${low ? 'low' : ''}">${fmt(p.lp)}</span></div>
        <div class="lp-track"><i class="lp-fill ${low ? 'low' : ''}" style="width:${lpPct}%"></i><span class="lp-ticks"></span></div>
      </div>
    </div>
    ${handStack}
    <div class="bar-meta">
      <span>DECK <b>${p.deck.length}</b></span>
      <span>GY <b>${p.gy.length}</b></span>
    </div>
  </div>`
}

export function renderSide(app, side, who) {
  const root = who === 'opponent' ? $('#oppSide') : $('#mySide')
  if (!root) return
  const st = app.state
  if (!st) {
    root.innerHTML = `<div class="player-bar ${who}"><div class="avatar"><span>?</span></div>
      <div class="p-main"><div class="p-name-row"><span class="p-name">CONNECTING…</span></div>
      <div class="lp-track skeleton-track"><i></i></div></div></div>
      <div class="board-grid skeleton-grid">
        ${Array.from({ length: 10 }).map((_, i) => `<div class="zone zone-skeleton" style="--i:${i}"></div>`).join('')}
      </div>`
    return
  }
  const base = side === 0 ? 1 : 13
  const monsters = Array.from({ length: 5 }).map((_, i) => zoneHTML(app, side, 'monster', i, base + i)).join('')
  const spells = Array.from({ length: 5 }).map((_, i) => zoneHTML(app, side, 'spell', i, base + 5 + i)).join('')
  root.innerHTML = `
    ${playerBarHTML(app, side, who)}
    <div class="board-grid">
      ${zoneHTML(app, side, 'emz', 0, base + 10)}
      ${monsters}
      ${zoneHTML(app, side, 'field', 0, base + 11)}
      ${spells}
      ${pilesHTML(app, side)}
    </div>`
}

/* ───────────────────────── CENTER ───────────────────────── */

function hintText(app) {
  const st = app.state
  if (!st) return app.connecting ? '対戦相手のルームに接続しています…' : 'ルームを準備しています…'
  if (st.winner != null) return 'デュエル終了'
  if (st.active !== app.mySide) {
    if (app.mode === 'cpu') return 'CPUが思考中… カードは止まらない'
    return '相手のターン… 次の一手を待て'
  }
  if (app.sel?.kind === 'place') {
    return app.sel.mode === 'setSpell' ? 'セットする魔法・罠ゾーンをタップ' : '召喚するモンスターゾーンをタップ'
  }
  if (app.sel?.kind === 'attacker') return '攻撃対象をタップ / DIRECT ATTACK'
  if (st.phase === 'battle') {
    if (st.noAttacks) return 'このターンの攻撃は封じられた'
    return '攻撃するモンスターをタップ'
  }
  return '手札を選んで、召喚・発動・セット'
}

function latestLog(st) {
  return st?.log?.length ? st.log[st.log.length - 1] : null
}

export function renderCenter(app) {
  const root = $('#centerBar')
  if (!root) return
  const st = app.state
  if (!st) {
    root.innerHTML = `<div class="turn-cluster"><span class="turn-kicker">STANDBY</span><b class="turn-status">CONNECTING</b></div>
      <div class="center-hint">ルーム接続中…</div><div class="center-actions"></div>`
    return
  }
  const myTurn = st.active === app.mySide
  const dead = st.winner != null
  const canAct = myTurn && !dead && !app.connecting
  const main = st.phase === 'main'
  const exReady = canSpecialSummon(st, app.mySide) && main && canAct
  const log = latestLog(st)
  const status = dead ? 'DUEL OVER' : myTurn ? 'YOUR TURN' : app.mode === 'cpu' ? 'CPU TURN' : 'ENEMY TURN'

  root.innerHTML = `
    <div class="turn-cluster">
      <div class="turn-badge"><span>TURN</span><b>${String(st.turn).padStart(2, '0')}</b></div>
      <div class="turn-info">
        <span class="turn-status ${myTurn ? 'mine' : 'theirs'} ${dead ? 'dead' : ''}">${status}</span>
        <span class="phase-pips">
          <i class="pip ${main ? 'on' : ''}">MAIN</i>
          <i class="pip ${!main ? 'on' : ''}">BATTLE</i>
        </span>
      </div>
    </div>
    <div class="center-mid">
      <p class="center-hint">${esc(hintText(app))}</p>
      <p class="center-log tone-${log?.tone || 'system'}"><span>LOG</span>${esc(log?.text || 'デュエル開始を待っています')}</p>
    </div>
    <div class="center-actions">
      <button class="btn btn-battle ${exReady ? 'has-ex' : ''}" data-act="battle"${!canAct || !main ? ' disabled' : ''}>BATTLE</button>
      <button class="btn btn-extra" data-act="extra"${!exReady ? ' disabled' : ''}>EX SUMMON</button>
      <button class="btn btn-end" data-act="endTurn"${!canAct ? ' disabled' : ''}>END TURN</button>
    </div>`
}

/* ───────────────────────── HAND + INFO ───────────────────────── */

function infoCardHTML(app, inst, hidden, context) {
  const c = CARDS[inst.id]
  if (hidden) {
    return `<div class="info-card mystery">
      <div class="info-title"><span class="rarity rarity-r">SET</span><b>セットカード</b><span class="info-type">正体不明</span></div>
      <p class="info-text">裏向きにセットされたカード。攻撃するか、効果のタイミングを待って正体が明らかになる。</p>
    </div>`
  }
  const st = app.state
  const side = context?.side
  const stats = c.type === 'monster'
    ? `<span class="info-stat">ATK <b>${fmt(side != null ? atkOf(st, side, inst) : c.atk)}</b></span>
       <span class="info-stat">DEF <b>${fmt(side != null ? defOf(st, side, inst) : c.def)}</b></span>`
    : `<span class="info-stat">${esc(cardTypeLabel(c))}</span>`
  return `<div class="info-card attr-${c.attr}">
    <div class="info-title">
      <span class="rarity rarity-${c.rarity || 'n'}">${RARITY_LABEL[c.rarity || 'n']}</span>
      <b>${esc(c.name)}</b>
      <span class="info-type">${esc(cardTypeLabel(c))}</span>
      ${stats}
    </div>
    <p class="info-text">${esc(c.text || '')}</p>
  </div>`
}

function actionButtonsForHand(app, inst, p) {
  const st = app.state
  const c = CARDS[inst.id]
  const myTurn = st.active === app.mySide
  const main = st.phase === 'main' && myTurn && st.winner == null && !app.connecting
  const freeMonster = p.monsters.some((z) => !z)
  const freeSpell = p.spells.some((z) => !z)
  const out = []

  if (c.type === 'monster') {
    const can = main && !p.hasSummoned && freeMonster && !c.extra
    out.push(button('召喚', { act: 'placeMode', mode: 'summon', uid: inst.uid }, !can, 'btn-summon'))
    out.push(button('守備セット', { act: 'placeMode', mode: 'setMonster', uid: inst.uid }, !can, 'btn-set'))
  } else if (c.type === 'spell') {
    const usable = main && spellUsable(st, app.mySide, inst)
    out.push(button('発動', { act: 'activateSpell', uid: inst.uid }, !usable, 'btn-activate'))
    out.push(button('セット', { act: 'placeMode', mode: 'setSpell', uid: inst.uid }, !(main && freeSpell), 'btn-set'))
  } else {
    out.push(button('セット', { act: 'placeMode', mode: 'setSpell', uid: inst.uid }, !(main && freeSpell), 'btn-set'))
  }
  out.push(button('キャンセル', { act: 'cancelSel' }, false, 'btn-ghost'))
  return out.join('')
}

export function infoPanelHTML(app) {
  const st = app.state
  const sel = app.sel
  if (!st) {
    return `<div class="info-empty"><span class="info-orb"></span><div><b>DUEL 24 ZONES</b><p>24のゾーン、画像なしのカード、止まらない演出。</p></div></div>`
  }
  const p = st.players[app.mySide]
  if (sel?.kind === 'hand') {
    const inst = p.hand.find((c) => c.uid === sel.uid)
    if (inst) {
      return `${infoCardHTML(app, inst, false, { side: app.mySide })}
        <div class="info-actions">${actionButtonsForHand(app, inst, p)}</div>`
    }
  }
  if (sel?.kind === 'place') {
    const inst = p.hand.find((c) => c.uid === sel.uid)
    if (inst) {
      return `${infoCardHTML(app, inst, false, { side: app.mySide })}
        <div class="info-actions"><span class="info-tip">光っているゾーンをタップ</span>${button('キャンセル', { act: 'cancelSel' }, false, 'btn-ghost')}</div>`
    }
  }
  if (sel?.kind === 'info') {
    const owner = st.players[sel.side]
    let inst = null
    if (sel.zoneKind === 'monster') inst = owner.monsters[sel.zoneIndex]
    if (sel.zoneKind === 'emz') inst = owner.emz
    if (sel.zoneKind === 'spell') inst = owner.spells[sel.zoneIndex]
    if (sel.zoneKind === 'field') inst = owner.field
    if (inst) {
      const hidden = inst.faceDown && sel.side !== app.mySide
      const ownSetSpell = sel.side === app.mySide && sel.zoneKind === 'spell' && inst.faceDown &&
        CARDS[inst.id].type === 'spell' && canActivateSet(st, app.mySide, sel.zoneIndex)
      return `${infoCardHTML(app, inst, hidden, { side: sel.side })}
        <div class="info-actions">
          ${ownSetSpell ? button('セット解除して発動', { act: 'activateSet', zone: sel.zoneIndex }, false, 'btn-activate') : ''}
          ${button('閉じる', { act: 'cancelSel' }, false, 'btn-ghost')}
        </div>`
    }
  }
  const log = latestLog(st)
  return `<div class="info-empty">
    <span class="info-orb"></span>
    <div><b>TAP A CARD</b><p>${esc(log?.text || '手札をタップしてカードを選択。光るゾーンへ配置しよう。')}</p></div>
    <span class="info-zones">24 ZONES</span>
  </div>`
}

export function renderHand(app) {
  const root = $('#handArea')
  if (!root) return
  const st = app.state
  const p = st ? st.players[app.mySide] : { hand: [], deck: [], extra: [] }
  const myTurn = st ? st.active === app.mySide : false
  const cards = p.hand.map((inst, i) => {
    const selected = app.sel?.kind === 'hand' && app.sel.uid === inst.uid
    const placing = app.sel?.kind === 'place' && app.sel.uid === inst.uid
    return `<button class="hand-card${selected ? ' selected' : ''}${placing ? ' placing' : ''}" data-act="hand" data-uid="${esc(inst.uid)}" style="--i:${i}" aria-label="${esc(CARDS[inst.id].name)}">
      ${cardHTML(app, inst, { side: app.mySide, index: i, hand: true })}
    </button>`
  }).join('')

  root.innerHTML = `
    <div class="info-panel">${infoPanelHTML(app)}</div>
    <div class="hand-bar">
      <div class="hand-meta">
        <span class="hand-title">HAND <b>${p.hand.length}</b></span>
        <span class="hand-sub">DECK ${p.deck.length} · EX ${p.extra.length}</span>
        <span class="turn-mini ${myTurn ? 'mine' : ''}">${myTurn ? 'YOUR MOVE' : 'WAITING'}</span>
      </div>
      <div class="hand-scroll">${cards || '<span class="hand-empty">手札なし</span>'}</div>
    </div>`
}

/* ───────────────────────── OVERLAY ───────────────────────── */

export function renderOverlay(app) {
  const root = $('#overlay')
  if (!root) return
  if (app.connecting) {
    root.className = 'overlay show overlay-connecting'
    root.innerHTML = `<div class="overlay-panel connect-panel">
      <div class="spinner"></div>
      <p class="eyebrow">ONLINE DUEL</p>
      <h2>相手のルームへ接続中</h2>
      <p class="overlay-copy">ROOM ${esc(app.hostCode || '----')} — ホストの応答を待っています。</p>
      <button class="btn btn-ghost" data-act="returnRoom">自分の部屋に戻る</button>
    </div>`
    return
  }
  if (app.hostGone) {
    root.className = 'overlay show overlay-gone'
    root.innerHTML = `<div class="overlay-panel gone-panel">
      <p class="eyebrow">CONNECTION LOST</p>
      <h2>HOST DISCONNECTED</h2>
      <p class="overlay-copy">ホストがルームを退出しました。自分のルームに戻ってCPUデュエルを再開できます。</p>
      <button class="btn btn-primary" data-act="returnRoom">自分の部屋に戻る</button>
    </div>`
    return
  }
  const st = app.state
  if (st && st.winner != null && app.resultReady) {
    const won = st.winner === app.mySide
    const me = st.players[app.mySide]
    const foe = st.players[1 - app.mySide]
    root.className = `overlay show ${won ? 'result-win' : 'result-lose'}`
    root.innerHTML = `<div class="overlay-panel result-panel">
      <div class="result-rays"></div>
      <p class="eyebrow">DUEL COMPLETE · TURN ${st.turn}</p>
      <h2 class="result-title">${won ? 'VICTORY' : 'DEFEAT'}</h2>
      <p class="result-reason">${esc(st.winReason || '')}</p>
      <div class="result-stats">
        <div><span>YOUR LP</span><b>${fmt(me.lp)}</b></div>
        <div><span>RIVAL LP</span><b>${fmt(foe.lp)}</b></div>
        <div><span>DAMAGE DEALT</span><b>${fmt(foe.lpLost || 0)}</b></div>
      </div>
      <div class="result-actions">
        <button class="btn btn-primary" data-act="rematch">再戦する</button>
        <button class="btn btn-ghost" data-act="openDrawer">ルーム一覧</button>
      </div>
      <p class="result-note">${app.mode === 'online'
        ? (app.role === 'guest' ? '再戦はホストにリクエストされます。' : '再戦すると同じ相手と新しいデュエルを開始します。')
        : '再戦するとCPUとの新しいデュエルを開始します。'}</p>
    </div>`
    return
  }
  root.className = 'overlay'
  root.innerHTML = ''
}

import { cardHTML } from './render.js'

const q = (sel) => document.querySelector(sel)
const reduced = () => false

export function ensureAudio(app) {
  if (app.audio) {
    if (app.audio.state === 'suspended') app.audio.resume().catch(() => {})
    return app.audio
  }
  try {
    const AC = window.AudioContext || window.webkitAudioContext
    if (AC) app.audio = new AC()
  } catch {
    app.audio = null
  }
  return app.audio
}

function tone(app, { freq = 440, endFreq = null, dur = 0.12, type = 'sine', vol = 0.04, delay = 0 }) {
  const ctx = app.audio
  if (!ctx) return
  try {
    const t0 = ctx.currentTime + delay
    const osc = ctx.createOscillator()
    const gain = ctx.createGain()
    osc.type = type
    osc.frequency.setValueAtTime(freq, t0)
    if (endFreq) osc.frequency.exponentialRampToValueAtTime(Math.max(30, endFreq), t0 + dur)
    gain.gain.setValueAtTime(0.0001, t0)
    gain.gain.exponentialRampToValueAtTime(vol, t0 + 0.012)
    gain.gain.exponentialRampToValueAtTime(0.0001, t0 + dur)
    osc.connect(gain)
    gain.connect(ctx.destination)
    osc.start(t0)
    osc.stop(t0 + dur + 0.03)
  } catch {
    /* audio is a nice-to-have only */
  }
}

export function sfx(app, kind) {
  if (!app.soundOn) return
  ensureAudio(app)
  if (!app.audio) return
  switch (kind) {
    case 'click':
      tone(app, { freq: 720, dur: 0.045, type: 'triangle', vol: 0.018 })
      break
    case 'draw':
      tone(app, { freq: 360, endFreq: 760, dur: 0.12, type: 'triangle', vol: 0.035 })
      break
    case 'summon':
      tone(app, { freq: 180, endFreq: 520, dur: 0.22, type: 'sawtooth', vol: 0.028 })
      tone(app, { freq: 520, endFreq: 880, dur: 0.2, type: 'sine', vol: 0.03, delay: 0.05 })
      break
    case 'special':
      tone(app, { freq: 220, endFreq: 990, dur: 0.42, type: 'sine', vol: 0.04 })
      break
    case 'attack':
      tone(app, { freq: 220, endFreq: 70, dur: 0.18, type: 'sawtooth', vol: 0.04 })
      break
    case 'damage':
      tone(app, { freq: 110, endFreq: 55, dur: 0.26, type: 'square', vol: 0.035 })
      break
    case 'heal':
      tone(app, { freq: 520, endFreq: 880, dur: 0.25, type: 'sine', vol: 0.03 })
      break
    case 'trap':
      tone(app, { freq: 300, endFreq: 180, dur: 0.32, type: 'triangle', vol: 0.04 })
      break
    case 'turn':
      tone(app, { freq: 440, endFreq: 660, dur: 0.16, type: 'triangle', vol: 0.025 })
      break
    case 'win':
      ;[523, 659, 784, 1046].forEach((f, i) => tone(app, { freq: f, dur: 0.22, type: 'triangle', vol: 0.045, delay: i * 0.1 }))
      break
    case 'lose':
      ;[330, 262, 196].forEach((f, i) => tone(app, { freq: f, dur: 0.3, type: 'sine', vol: 0.04, delay: i * 0.14 }))
      break
    case 'error':
      tone(app, { freq: 160, dur: 0.1, type: 'square', vol: 0.025 })
      break
    default:
      break
  }
}

function anim(el, frames, opts = {}) {
  if (!el) return null
  try {
    const a = el.animate(frames, {
      duration: opts.duration || 360,
      easing: opts.easing || 'cubic-bezier(.2,.9,.2,1)',
      delay: opts.delay || 0,
      fill: 'none',
    })
    if (opts.remove !== false) a.onfinish = () => { try { a.cancel() } catch { /* ignore */ } }
    return a
  } catch {
    return null
  }
}

function cardEl(uid) {
  if (!uid) return null
  const safe = String(uid).replace(/["\\]/g, '')
  return q(`.card[data-uid="${safe}"]`)
}

function zoneEl(side, kind, index) {
  return q(`.zone[data-side="${side}"][data-kind="${kind}"][data-index="${index}"]`)
}

function lpEl(side) {
  return q(`[data-lp-side="${side}"]`)
}

function centerEl() {
  return q('#centerBar')
}

function layer() {
  return q('#fxLayer')
}

function flash(kind = 'hit') {
  const el = layer()
  if (!el) return
  const f = document.createElement('div')
  f.className = `fx-flash ${kind}`
  el.appendChild(f)
  setTimeout(() => f.remove(), 420)
}

function shake(app) {
  const el = q('#app')
  if (!el) return
  el.classList.remove('shake')
  void el.offsetWidth
  el.classList.add('shake')
  setTimeout(() => el.classList.remove('shake'), 380)
}

function glowZone(side, kind, index, cls = 'zone-flash') {
  const el = zoneEl(side, kind, index)
  if (!el) return
  el.classList.remove(cls)
  void el.offsetWidth
  el.classList.add(cls)
  setTimeout(() => el.classList.remove(cls), 900)
}

function floatText(app, side, text, cls = 'bad') {
  const anchor = lpEl(side)
  const host = layer()
  if (!anchor || !host) return
  const r = anchor.getBoundingClientRect()
  const el = document.createElement('div')
  el.className = `fx-float ${cls}`
  el.textContent = text
  el.style.left = `${r.left + r.width * 0.5}px`
  el.style.top = `${r.top + 14}px`
  host.appendChild(el)
  anim(el, [
    { transform: 'translate(-50%, 6px) scale(.7)', opacity: 0 },
    { transform: 'translate(-50%, -16px) scale(1.12)', opacity: 1, offset: 0.25 },
    { transform: 'translate(-50%, -72px) scale(1)', opacity: 0 },
  ], { duration: 950, easing: 'cubic-bezier(.2,.8,.2,1)' })
  setTimeout(() => el.remove(), 1000)
}

function slashAt(el, kind = 'slash') {
  const host = layer()
  if (!host) return
  const target = el || centerEl()
  if (!target) return
  const r = target.getBoundingClientRect()
  const s = document.createElement('div')
  s.className = `fx-slash ${kind}`
  s.style.left = `${r.left + r.width / 2}px`
  s.style.top = `${r.top + r.height / 2}px`
  s.innerHTML = '<i></i><i></i><b></b>'
  host.appendChild(s)
  anim(s, [
    { transform: 'translate(-50%,-50%) scale(.2) rotate(-18deg)', opacity: 0 },
    { transform: 'translate(-50%,-50%) scale(1.15) rotate(0deg)', opacity: 1, offset: 0.3 },
    { transform: 'translate(-50%,-50%) scale(1.5) rotate(6deg)', opacity: 0 },
  ], { duration: 420, easing: 'cubic-bezier(.1,.8,.2,1)' })
  setTimeout(() => s.remove(), 450)
}

function ghostCard(app, ev) {
  const zone = zoneEl(ev.side, ev.kind, ev.index)
  const host = layer()
  if (!host) return
  const r = zone ? zone.getBoundingClientRect() : null
  const ghost = document.createElement('div')
  ghost.className = 'fx-ghost'
  try {
    ghost.innerHTML = cardHTML(app, { uid: `ghost-${Date.now()}`, id: ev.cardId, faceDown: ev.faceDown, pos: 'atk', atkBonus: 0 }, { side: ev.side, index: 0 })
  } catch {
    ghost.innerHTML = ''
  }
  const x = r ? r.left : window.innerWidth / 2 - 40
  const y = r ? r.top : window.innerHeight / 2 - 50
  const w = r ? r.width : 80
  const h = r ? r.height : 112
  ghost.style.left = `${x}px`
  ghost.style.top = `${y}px`
  ghost.style.width = `${w}px`
  ghost.style.height = `${h}px`
  host.appendChild(ghost)
  anim(ghost, [
    { transform: 'scale(1) rotate(0)', opacity: 1, filter: 'brightness(1)' },
    { transform: 'scale(1.12) rotate(-4deg)', opacity: 1, filter: 'brightness(1.8)', offset: 0.2 },
    { transform: 'scale(.6) rotate(14deg) translateY(18px)', opacity: 0, filter: 'brightness(2.4) blur(4px)' },
  ], { duration: 620, easing: 'cubic-bezier(.2,.7,.3,1)' })
  setTimeout(() => ghost.remove(), 650)

  const burst = document.createElement('div')
  burst.className = 'fx-burst'
  burst.style.left = `${x + w / 2}px`
  burst.style.top = `${y + h / 2}px`
  burst.innerHTML = '<i></i><i></i><i></i><i></i><i></i><i></i>'
  host.appendChild(burst)
  setTimeout(() => burst.remove(), 600)
}

function lunge(app, from, to, direct) {
  if (!from) {
    slashAt(to)
    return
  }
  const fr = from.getBoundingClientRect()
  const tr = to ? to.getBoundingClientRect() : centerEl()?.getBoundingClientRect()
  if (!tr) return
  let dx = (tr.left + tr.width / 2) - (fr.left + fr.width / 2)
  let dy = (tr.top + tr.height / 2) - (fr.top + fr.height / 2)
  const max = 190
  const len = Math.hypot(dx, dy) || 1
  if (len > max) { dx = (dx / len) * max; dy = (dy / len) * max }
  anim(from, [
    { transform: 'translate(0,0) scale(1) rotate(0)' },
    { transform: `translate(${dx * 0.55}px, ${dy * 0.55}px) scale(1.14) rotate(${direct ? -6 : -4}deg)`, offset: 0.45 },
    { transform: 'translate(0,0) scale(1) rotate(0)' },
  ], { duration: 420, easing: 'cubic-bezier(.2,.8,.2,1)' })
  slashAt(to, direct ? 'slash-direct' : 'slash')
}

export function playEvents(app, events) {
  if (!Array.isArray(events)) return
  events.forEach((ev, i) => {
    setTimeout(() => {
      try { playEvent(app, ev) } catch { /* never break the duel for an effect */ }
    }, i * 90)
  })
}

function playEvent(app, ev) {
  if (!ev || !ev.type) return
  switch (ev.type) {
    case 'start': {
      flash('start')
      sfx(app, 'turn')
      break
    }
    case 'draw': {
      sfx(app, 'draw')
      const el = cardEl(ev.uid)
      if (el) {
        anim(el.closest('.hand-card') || el, [
          { transform: 'translateY(32px) scale(.8) rotate(-4deg)', opacity: 0 },
          { transform: 'translateY(0) scale(1) rotate(0)', opacity: 1 },
        ], { duration: 380, easing: 'cubic-bezier(.2,1.2,.4,1)' })
      }
      break
    }
    case 'summon':
    case 'setMonster':
    case 'special': {
      sfx(app, ev.type === 'special' ? 'special' : 'summon')
      const el = cardEl(ev.uid)
      if (el) {
        anim(el, ev.type === 'setMonster'
          ? [
              { transform: 'rotateY(0deg) scale(.8)', opacity: 0.2 },
              { transform: 'rotateY(160deg) scale(1.05)', opacity: 1, offset: 0.7 },
              { transform: 'rotateY(180deg) scale(1)', opacity: 1 },
            ]
          : [
              { transform: 'translateY(34px) scale(.55) rotate(-5deg)', opacity: 0, filter: 'brightness(2)' },
              { transform: 'translateY(0) scale(1.06) rotate(0)', opacity: 1, filter: 'brightness(1.4)', offset: 0.6 },
              { transform: 'scale(1)', filter: 'brightness(1)' },
            ], { duration: 480, easing: 'cubic-bezier(.2,1.1,.4,1)' })
      }
      glowZone(ev.side, ev.zoneKind || 'monster', ev.index || 0, ev.type === 'special' ? 'zone-special' : 'zone-flash')
      flash('summon')
      break
    }
    case 'setSpell': {
      sfx(app, 'click')
      glowZone(ev.side, 'spell', ev.zone, 'zone-set')
      break
    }
    case 'spell':
    case 'trap': {
      sfx(app, ev.type === 'trap' ? 'trap' : 'special')
      if (ev.zone != null) glowZone(ev.side, 'spell', ev.zone, ev.type === 'trap' ? 'zone-trap' : 'zone-spell')
      else {
        const c = centerEl()
        if (c) anim(c, [{ filter: 'brightness(1)' }, { filter: 'brightness(1.8)' }, { filter: 'brightness(1)' }], { duration: 420 })
      }
      flash(ev.type === 'trap' ? 'trap' : 'spell')
      break
    }
    case 'field': {
      sfx(app, 'special')
      glowZone(ev.side, 'field', 0, 'zone-field')
      flash('spell')
      break
    }
    case 'attack': {
      sfx(app, 'attack')
      const from = ev.from ? cardEl(ev.from.uid) : null
      let to = null
      if (ev.to) to = cardEl(ev.to.uid) || zoneEl(ev.side === 0 ? 1 : 0, ev.to.kind, ev.to.index)
      if (ev.direct) to = lpEl(ev.side === 0 ? 1 : 0)
      lunge(app, from, to, !!ev.direct)
      break
    }
    case 'damage': {
      sfx(app, 'damage')
      flash('hit')
      shake(app)
      floatText(app, ev.side, `-${ev.amount}`, 'bad')
      const lp = lpEl(ev.side)
      if (lp) anim(lp.querySelector('.lp-fill'), [
        { filter: 'brightness(1)' }, { filter: 'brightness(2.2)' }, { filter: 'brightness(1)' },
      ], { duration: 400 })
      break
    }
    case 'heal': {
      sfx(app, 'heal')
      floatText(app, ev.side, `+${ev.amount}`, 'good')
      break
    }
    case 'destroy': {
      ghostCard(app, ev)
      sfx(app, 'damage')
      shake(app)
      break
    }
    case 'equipLost': {
      glowZone(ev.side, 'spell', ev.zone, 'zone-trap')
      break
    }
    case 'turn': {
      sfx(app, 'turn')
      const c = centerEl()
      if (c) anim(c, [
        { filter: 'brightness(1)' },
        { filter: 'brightness(1.7)' },
        { filter: 'brightness(1)' },
      ], { duration: 520 })
      break
    }
    case 'phase': {
      sfx(app, 'click')
      flash('phase')
      break
    }
    case 'result': {
      sfx(app, ev.winner === app.mySide ? 'win' : 'lose')
      flash(ev.winner === app.mySide ? 'win' : 'lose')
      break
    }
    case 'deckout': {
      flash('hit')
      break
    }
    default:
      break
  }
}

import { CARDS } from './cards.js'
import {
  createDuel, applyAction, aiChooseAction, zoneMonster,
  countMonsters, canSpecialSummon,
} from './engine.js'
import { RoomNet, randomName } from './rooms.js'
import {
  $, esc, renderTopbar, renderSide, renderCenter, renderHand,
  renderOverlay, roomCodeFor,
} from './render.js'
import { renderDrawer, renderModal } from './panels.js'
import { ensureAudio, sfx, playEvents } from './fx.js'

const NAME_KEY = 'duel24.name'
const SOUND_KEY = 'duel24.sound'

function loadName() {
  let name = ''
  try { name = sessionStorage.getItem(NAME_KEY) || '' } catch { /* ignore */ }
  if (!name) {
    name = randomName()
    try { sessionStorage.setItem(NAME_KEY, name) } catch { /* ignore */ }
  }
  return name
}

function makeClientId() {
  try { return `c${crypto.randomUUID().replace(/-/g, '').slice(0, 14)}` } catch { return `c${Math.random().toString(36).slice(2, 12)}` }
}

class DuelApp {
  constructor() {
    this.clientId = makeClientId()
    this.name = loadName()
    this.ownRoomId = null
    this.inRoomId = null
    this.role = 'host'
    this.mode = 'cpu'
    this.mySide = 0
    this.state = null
    this.guestId = null
    this.guestName = null
    this.hostId = null
    this.hostName = null
    this.hostCode = null
    this.lastGuestSeen = 0
    this.sel = null
    this.modal = null
    this.drawerOpen = false
    this.connecting = false
    this.hostGone = false
    this.resultReady = false
    this.soundOn = true
    this.audio = null
    this.cpuTimer = null
    this.joinTimer = null
    this.resultTimer = null
    this.toastTimer = null
    this.cleaned = false
    try { this.soundOn = sessionStorage.getItem(SOUND_KEY) !== 'off' } catch { /* ignore */ }
  }

  init() {
    this.net = new RoomNet({
      clientId: this.clientId,
      name: this.name,
      onMessage: (msg) => this.onMessage(msg),
      onRooms: () => {
        this.renderTopbar()
        if (this.drawerOpen) this.renderDrawerSafe()
      },
    })
    this.bindEvents()

    const own = this.net.ensureOwnRoom()
    this.ownRoomId = own.id
    this.inRoomId = own.id
    this.hostId = this.clientId
    this.hostCode = own.code
    this.startCpuDuel(true)

    this.tickTimer = setInterval(() => {
      this.renderTopbar()
      if (this.drawerOpen) this.renderDrawerSafe()
    }, 2600)

    this.pingTimer = setInterval(() => {
      if (this.role === 'guest' && this.hostId) {
        this.net.send({ type: 'ping', roomId: this.inRoomId, from: this.clientId, to: this.hostId })
      }
    }, 4000)

    this.watchTimer = setInterval(() => this.watchConnections(), 7000)

    const joinId = new URLSearchParams(location.search).get('join')
    if (joinId) {
      try { history.replaceState({}, '', location.pathname + location.hash) } catch { /* ignore */ }
      setTimeout(() => {
        const ok = this.joinRoomById(joinId, true)
        if (!ok) this.toast('指定されたルームが見つかりません。CPU戦を続けます。', 'warn', 4200)
      }, 850)
    } else {
      setTimeout(() => this.toast('自分のルームを自動生成して入室しました。CPUが相手を務めています。', 'info', 4800), 900)
    }
  }

  /* ────────────────────────── RENDER ────────────────────────── */

  render() {
    if (!this.net) return
    this.pruneSelection()
    renderTopbar(this)
    renderSide(this, 1 - this.mySide, 'opponent')
    renderCenter(this)
    renderSide(this, this.mySide, 'self')
    renderHand(this)
    renderOverlay(this)
    if (this.drawerOpen) this.renderDrawerSafe()
    renderModal(this)
  }

  renderDrawerSafe() {
    if (document.activeElement?.id === 'nameInput') return
    renderDrawer(this)
  }

  pruneSelection() {
    const st = this.state
    if (!st) { this.sel = null; return }
    const sel = this.sel
    if (!sel) return
    const my = st.players[this.mySide]
    if (sel.kind === 'hand' || sel.kind === 'place') {
      if (!my.hand.some((c) => c.uid === sel.uid)) this.sel = null
    } else if (sel.kind === 'attacker') {
      if (!zoneMonster(my, sel.zoneKind, sel.zoneIndex)) this.sel = null
    } else if (sel.kind === 'info') {
      const p = st.players[sel.side]
      const inst = this.instAt(sel.side, sel.zoneKind, sel.zoneIndex)
      if (!inst) this.sel = null
    }
  }

  instAt(side, kind, index) {
    const st = this.state
    if (!st) return null
    const p = st.players[side]
    if (kind === 'monster') return p.monsters[index] || null
    if (kind === 'spell') return p.spells[index] || null
    if (kind === 'field') return p.field
    if (kind === 'emz') return p.emz
    return null
  }

  toast(message, tone = 'info', ms = 3000) {
    const el = $('#toast')
    if (!el) return
    clearTimeout(this.toastTimer)
    el.textContent = message
    el.className = `toast show tone-${tone}`
    this.toastTimer = setTimeout(() => { el.className = 'toast' }, ms)
  }

  /* ────────────────────────── EVENTS ────────────────────────── */

  bindEvents() {
    document.addEventListener('click', (e) => {
      const el = e.target.closest('[data-act]')
      if (!el || el.disabled) return
      this.handleAction(el.dataset.act, el, e)
    })
    document.addEventListener('pointerdown', () => ensureAudio(this), { once: true })
    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape') {
        if (this.modal) { this.closeModal(); return }
        if (this.drawerOpen) { this.closeDrawer(); return }
        if (this.sel) { this.sel = null; this.render() }
      }
      if (e.key === 'Enter' && e.target?.id === 'nameInput') {
        e.preventDefault()
        this.saveName()
      }
    })
    window.addEventListener('beforeunload', () => this.cleanup())
    window.addEventListener('pagehide', () => this.cleanup())
  }

  handleAction(act, el) {
    switch (act) {
      case 'openDrawer': this.openDrawer(); break
      case 'closeDrawer': this.closeDrawer(); break
      case 'toggleSound': this.toggleSound(); break
      case 'hand': this.selectHand(el.dataset.uid); break
      case 'placeMode': this.placeMode(el.dataset.mode, el.dataset.uid); break
      case 'cancelSel': this.sel = null; this.render(); break
      case 'zone': this.onZone(Number(el.dataset.side), el.dataset.kind, Number(el.dataset.index)); break
      case 'battle': this.doAction({ type: 'toBattle' }); break
      case 'endTurn': this.doAction({ type: 'endTurn' }); break
      case 'extra': this.openExtraModal(); break
      case 'directAttack': this.directAttack(); break
      case 'openPile': this.openPile(Number(el.dataset.side), el.dataset.pile); break
      case 'closeModal': this.closeModal(); break
      case 'specialSummon':
        this.doAction({ type: 'specialSummon', cardId: el.dataset.cardId })
        this.closeModal()
        break
      case 'activateSpell':
        this.doAction({ type: 'activateSpell', handUid: el.dataset.uid })
        break
      case 'activateSet':
        this.doAction({ type: 'activateSet', zone: Number(el.dataset.zone) })
        break
      case 'joinRoom': this.joinRoomById(el.dataset.room); break
      case 'returnRoom': this.returnToOwnRoom(); break
      case 'copyCode': this.copyText(el.dataset.code, el); break
      case 'openTab': this.openOpponentTab(); break
      case 'saveName': this.saveName(); break
      case 'rematch': this.rematch(); break
      case 'surrender': this.surrender(); break
      default: break
    }
  }

  openDrawer() {
    this.drawerOpen = true
    document.body.classList.add('drawer-open')
    renderDrawer(this)
    sfx(this, 'click')
  }

  closeDrawer() {
    this.drawerOpen = false
    document.body.classList.remove('drawer-open')
  }

  openModalState(modal) {
    this.modal = modal
    document.body.classList.add('modal-open')
    renderModal(this)
  }

  closeModal() {
    this.modal = null
    document.body.classList.remove('modal-open')
    renderModal(this)
  }

  openPile(side, pile) {
    if (!this.state) return
    this.openModalState({ type: 'pile', side, pile })
    sfx(this, 'click')
  }

  openExtraModal() {
    if (!this.state) return
    if (!canSpecialSummon(this.state, this.mySide)) {
      this.toast('EX特殊召喚には自分モンスター2体以上・空のEXゾーンが必要です', 'warn')
      return
    }
    if (this.state.active !== this.mySide || this.state.phase !== 'main') {
      this.toast('自分のメインフェイズでEX特殊召喚できます', 'warn')
      return
    }
    this.openModalState({ type: 'pile', side: this.mySide, pile: 'extra' })
  }

  /* ────────────────────────── SELECTION ────────────────────────── */

  selectHand(uid) {
    if (!this.state) return
    if (this.sel?.kind === 'hand' && this.sel.uid === uid) {
      this.sel = null
    } else {
      this.sel = { kind: 'hand', uid }
      sfx(this, 'click')
    }
    this.render()
  }

  placeMode(mode, uid) {
    const st = this.state
    if (!st) return
    const p = st.players[this.mySide]
    const inst = p.hand.find((c) => c.uid === uid)
    if (!inst) return
    if (st.active !== this.mySide) { this.toast('自分のターンではありません', 'warn'); return }
    if (st.phase !== 'main') { this.toast('メインフェイズで配置してください', 'warn'); return }
    if ((mode === 'summon' || mode === 'setMonster') && p.hasSummoned) {
      this.toast('このターンは既に召喚済みです', 'warn')
      return
    }
    this.sel = { kind: 'place', uid, mode }
    sfx(this, 'click')
    this.render()
  }

  onZone(side, kind, index) {
    const st = this.state
    if (!st) return
    const mine = side === this.mySide
    const inst = this.instAt(side, kind, index)
    const sel = this.sel

    if (sel?.kind === 'place' && mine) {
      const expected = sel.mode === 'setSpell' ? 'spell' : 'monster'
      if (kind !== expected) { this.toast(expected === 'spell' ? '魔法・罠ゾーンを選択してください' : 'モンスターゾーンを選択してください', 'warn'); return }
      if (inst) { this.toast('そのゾーンは埋まっています', 'warn'); return }
      const type = sel.mode === 'setSpell' ? 'setSpell' : sel.mode
      this.doAction({ type, handUid: sel.uid, zone: index })
      return
    }

    if (sel?.kind === 'attacker') {
      if (!mine && (kind === 'monster' || kind === 'emz') && inst) {
        this.doAction({
          type: 'attack', zoneKind: sel.zoneKind, zoneIndex: sel.zoneIndex,
          targetKind: kind, targetIndex: index,
        })
        return
      }
      if (mine) {
        this.selectAttacker(side, kind, index)
        return
      }
      return
    }

    if (mine && kind === 'emz' && !inst && st.phase === 'main' && st.active === this.mySide && canSpecialSummon(st, this.mySide)) {
      this.openExtraModal()
      return
    }

    if (st.phase === 'battle' && st.active === this.mySide && mine && !st.noAttacks && inst &&
        !inst.faceDown && inst.pos === 'atk' && !inst.hasAttacked) {
      this.selectAttacker(side, kind, index)
      return
    }

    if (inst) {
      this.sel = { kind: 'info', side, zoneKind: kind, zoneIndex: index }
      sfx(this, 'click')
      this.render()
    } else {
      this.sel = null
      this.render()
    }
  }

  selectAttacker(side, kind, index) {
    const sel = this.sel
    if (sel?.kind === 'attacker' && sel.zoneKind === kind && sel.zoneIndex === index) {
      this.sel = null
    } else {
      this.sel = { kind: 'attacker', zoneKind: kind, zoneIndex: index }
      sfx(this, 'click')
    }
    this.render()
  }

  directAttack() {
    if (this.sel?.kind !== 'attacker') return
    const st = this.state
    if (!st) return
    const attacker = zoneMonster(st.players[this.mySide], this.sel.zoneKind, this.sel.zoneIndex)
    if (!attacker) return
    const foe = st.players[1 - this.mySide]
    if (countMonsters(foe) > 0 && !CARDS[attacker.id].direct) {
      this.toast('相手モンスターがいるため直接攻撃できません', 'warn')
      return
    }
    this.doAction({
      type: 'attack', zoneKind: this.sel.zoneKind, zoneIndex: this.sel.zoneIndex,
      targetKind: 'direct', targetIndex: 0,
    })
  }

  /* ────────────────────────── ACTIONS ────────────────────────── */

  doAction(action) {
    const st = this.state
    if (!st) return false
    if (st.winner != null) { this.toast('デュエルは終了しています'); return false }
    if (this.connecting || this.hostGone) return false
    if (st.active !== this.mySide) { this.toast('相手のターンです', 'warn'); return false }

    if (this.role === 'guest') {
      if (!this.hostId) return false
      this.net.send({
        type: 'action', roomId: this.inRoomId, from: this.clientId, to: this.hostId, action,
      })
      sfx(this, 'click')
      return true
    }
    return this.applyLocal(this.mySide, action)
  }

  applyLocal(side, action) {
    if (!this.state) return false
    const res = applyAction(this.state, side, action)
    if (!res.ok) {
      this.toast(res.error || '実行できません', 'warn')
      sfx(this, 'error')
      return false
    }
    this.sel = null
    this.render()
    playEvents(this, res.events)
    this.afterLocal(res.events)
    return true
  }

  afterLocal(events) {
    if (this.role === 'host' && this.mode === 'online' && this.guestId) this.sendState(events)
    if (this.state?.winner != null) { this.scheduleResult(); return }
    if (this.mode === 'cpu' && this.role === 'host') {
      if (this.state.active === 1 && this.state.players[1].isCPU) this.scheduleCPU()
      else clearTimeout(this.cpuTimer)
    }
  }

  scheduleCPU() {
    clearTimeout(this.cpuTimer)
    if (this.mode !== 'cpu' || this.role !== 'host' || !this.state) return
    if (this.state.winner != null || this.state.active !== 1) return
    if (!this.state.players[1].isCPU) return
    this.cpuTimer = setTimeout(() => {
      if (this.mode !== 'cpu' || this.role !== 'host' || !this.state) return
      if (this.state.winner != null || this.state.active !== 1) return
      if (!this.state.players[1].isCPU) return
      const action = aiChooseAction(this.state, 1) || { type: 'endTurn' }
      const res = applyAction(this.state, 1, action)
      if (!res.ok) {
        const fb = applyAction(this.state, 1, { type: 'endTurn' })
        if (!fb.ok) return
        this.render()
        playEvents(this, fb.events)
        this.afterLocal(fb.events)
        return
      }
      this.sel = null
      this.render()
      playEvents(this, res.events)
      this.afterLocal(res.events)
    }, 920)
  }

  scheduleResult() {
    if (!this.state || this.state.winner == null) { this.resultReady = false; renderOverlay(this); return }
    if (this.resultReady) { renderOverlay(this); return }
    clearTimeout(this.resultTimer)
    this.resultTimer = setTimeout(() => {
      if (!this.state || this.state.winner == null) return
      this.resultReady = true
      renderOverlay(this)
      sfx(this, this.state.winner === this.mySide ? 'win' : 'lose')
    }, 850)
  }

  rematch() {
    if (this.mode === 'online' && this.role === 'guest') {
      if (!this.hostId) return
      this.net.send({ type: 'rematch', roomId: this.inRoomId, from: this.clientId, to: this.hostId })
      this.toast('再戦をホストにリクエストしました', 'info', 3200)
      return
    }
    if (this.mode === 'online' && this.role === 'host' && this.guestId) {
      this.startOnlineDuel(this.guestId, this.guestName)
      return
    }
    this.startCpuDuel()
  }

  surrender() {
    if (!this.state || this.state.winner != null) return
    let ok = false
    try { ok = window.confirm('本当に投了しますか？') } catch { ok = true }
    if (ok) this.doAction({ type: 'surrender' })
  }

  /* ────────────────────────── DUEL LIFECYCLE ────────────────────────── */

  clearTimers() {
    clearTimeout(this.cpuTimer)
    clearTimeout(this.joinTimer)
    clearTimeout(this.resultTimer)
    this.cpuTimer = null
    this.joinTimer = null
    this.resultTimer = null
  }

  startCpuDuel(initial = false) {
    this.clearTimers()
    if (!this.net.ownRoom()) this.net.ensureOwnRoom()
    this.ownRoomId = this.net.ownRoomId
    this.ownRoomId = this.net.ownRoom()?.id || this.ownRoomId
    this.inRoomId = this.ownRoomId
    this.hostId = this.clientId
    this.guestId = null
    this.guestName = null
    this.hostCode = this.net.ownRoom()?.code || null
    this.role = 'host'
    this.mode = 'cpu'
    this.mySide = 0
    this.connecting = false
    this.hostGone = false
    this.resultReady = false
    this.sel = null
    this.modal = null
    document.body.classList.remove('modal-open')

    this.state = createDuel([this.name, 'CPU・デュエリスト'], 0, { cpuOpponent: true, mode: 'cpu' })
    this.net.updateRoom(this.ownRoomId, {
      hostName: this.name, mode: 'cpu', joinable: true, guestId: null, guestName: null,
    })
    this.render()
    playEvents(this, [{ type: 'start' }])
    if (!initial) this.toast('新しいデュエルを開始しました', 'info')
  }

  startOnlineDuel(guestId, guestName) {
    if (!guestId) return
    this.clearTimers()
    const room = this.net.ownRoom()
    this.ownRoomId = room?.id || this.ownRoomId
    this.inRoomId = this.ownRoomId
    this.hostId = this.clientId
    this.guestId = guestId
    this.guestName = guestName || 'RIVAL'
    this.hostCode = room?.code || this.hostCode
    this.role = 'host'
    this.mode = 'online'
    this.mySide = 0
    this.connecting = false
    this.hostGone = false
    this.resultReady = false
    this.sel = null
    this.modal = null
    document.body.classList.remove('modal-open')
    this.lastGuestSeen = Date.now()

    const starter = Math.random() < 0.5 ? 0 : 1
    this.state = createDuel([this.name, this.guestName], starter, { cpuOpponent: false, mode: 'online' })
    this.net.updateRoom(this.ownRoomId, {
      hostName: this.name, mode: 'pvp', joinable: false,
      guestId: this.guestId, guestName: this.guestName,
    })
    this.render()
    this.sendState([{ type: 'start' }])
    playEvents(this, [{ type: 'start' }])
    this.toast(`${this.guestName} が乱入！ 対人デュエル開始`, 'pvp', 3800)
  }

  sendState(events = []) {
    if (!this.guestId) return
    this.net.send({
      type: 'state', roomId: this.ownRoomId, from: this.clientId, to: this.guestId,
      state: this.state, events,
    })
  }

  returnToOwnRoom() {
    if (this.role === 'guest' || this.role === 'guest-pending' || this.role === 'guest-left') {
      if (this.hostId) {
        this.net.send({ type: 'leave', roomId: this.inRoomId, from: this.clientId, name: this.name })
      }
    }
    if (!this.net.ownRoom()) this.net.ensureOwnRoom()
    this.ownRoomId = this.net.ownRoom()?.id || this.net.ownRoomId
    this.net.setAway(false)
    this.net.updateRoom(this.ownRoomId, {
      hostName: this.name, mode: 'cpu', joinable: true, guestId: null, guestName: null,
    })
    this.guestId = null
    this.guestName = null
    this.hostId = this.clientId
    this.hostCode = this.net.ownRoom()?.code || null
    this.hostGone = false
    this.connecting = false
    this.resultReady = false
    this.startCpuDuel()
    this.closeDrawer()
    this.toast('自分のルームに戻りました', 'info')
  }

  /* ────────────────────────── ROOMS ────────────────────────── */

  joinRoomById(roomId, auto = false) {
    if (!roomId) return false
    if (this.connecting) return false
    const rooms = this.net.list()
    const room = rooms.find((r) => r.id === roomId)
    if (!room) {
      this.toast('ルームが見つかりません', 'warn')
      return false
    }
    if (room.hostId === this.clientId) {
      if (!auto) this.toast('これは自分のルームです')
      return false
    }
    if (!this.net.fresh(room)) {
      this.toast('そのルームは応答がありません', 'warn')
      return false
    }
    if (!room.joinable || room.mode === 'pvp' || room.mode === 'away') {
      this.toast('そのルームは満室です', 'warn')
      return false
    }
    if (this.role === 'guest' && this.inRoomId === roomId) {
      this.toast('既にこのルームに入室しています')
      return false
    }

    if (this.role === 'guest' && this.hostId && this.inRoomId !== roomId) {
      this.net.send({ type: 'leave', roomId: this.inRoomId, from: this.clientId, name: this.name })
    }

    this.clearTimers()
    this.net.setAway(true)
    this.inRoomId = room.id
    this.hostId = room.hostId
    this.hostName = room.hostName
    this.hostCode = room.code
    this.role = 'guest-pending'
    this.mode = 'online'
    this.mySide = 1
    this.connecting = true
    this.hostGone = false
    this.resultReady = false
    this.sel = null
    this.state = null
    this.modal = null
    document.body.classList.remove('modal-open')
    this.render()
    this.closeDrawer()
    this.net.send({ type: 'join', roomId: room.id, from: this.clientId, name: this.name })

    this.joinTimer = setTimeout(() => {
      if (this.connecting && this.role === 'guest-pending') {
        this.connecting = false
        this.toast('接続できませんでした。自分の部屋に戻ります。', 'warn', 3600)
        this.returnToOwnRoom()
      }
    }, 6000)
    return true
  }

  openOpponentTab() {
    if (this.role === 'guest' || this.role === 'guest-pending') {
      this.toast('自分の部屋に戻ってから開いてください', 'warn')
      return
    }
    const room = this.net.ownRoom()
    if (!room) { this.toast('ルームがありません', 'warn'); return }
    const url = `${location.origin}${location.pathname}?join=${encodeURIComponent(room.id)}`
    let win = null
    try { win = window.open(url, '_blank') } catch { win = null }
    if (!win) {
      this.toast('ポップアップがブロックされました', 'warn', 3600)
    } else {
      this.toast('別タブで対戦相手を開きました。自動でこのルームに参加します。', 'info', 4200)
      this.closeDrawer()
    }
  }

  async copyText(text, el) {
    if (!text) return
    try {
      await navigator.clipboard.writeText(text)
      this.toast(`ルームコード ${text} をコピーしました`, 'info')
    } catch {
      try {
        const ta = document.createElement('textarea')
        ta.value = text
        ta.style.position = 'fixed'
        ta.style.opacity = '0'
        document.body.appendChild(ta)
        ta.select()
        document.execCommand('copy')
        ta.remove()
        this.toast(`ルームコード ${text}`, 'info')
      } catch {
        this.toast(`ルームコード ${text}`, 'info')
      }
    }
    sfx(this, 'click')
  }

  saveName() {
    const input = $('#nameInput')
    const name = (input?.value || '').trim().slice(0, 16) || randomName()
    this.name = name
    try { sessionStorage.setItem(NAME_KEY, name) } catch { /* ignore */ }
    this.net.name = name
    this.net.updateRoom(this.net.ownRoomId, { hostName: name })
    if (this.state && this.role === 'host') {
      this.state.players[0].name = name
      if (this.mode === 'online' && this.guestId) this.sendState([])
    }
    this.render()
    this.toast(`デュエリスト名を「${name}」に変更しました`, 'info')
  }

  toggleSound() {
    this.soundOn = !this.soundOn
    try { sessionStorage.setItem(SOUND_KEY, this.soundOn ? 'on' : 'off') } catch { /* ignore */ }
    if (this.soundOn) { ensureAudio(this); sfx(this, 'click') }
    renderTopbar(this)
  }

  /* ────────────────────────── NETWORK ────────────────────────── */

  onMessage(msg) {
    if (!msg || !msg.type) return
    switch (msg.type) {
      case 'join':
        this.onJoin(msg)
        break
      case 'state':
        this.onStateMessage(msg)
        break
      case 'action':
        this.onGuestAction(msg)
        break
      case 'leave':
        if (msg.roomId === this.ownRoomId && msg.from === this.guestId) this.onGuestLeft()
        break
      case 'hostLeft':
        if (msg.to === this.clientId && msg.roomId === this.inRoomId) this.handleHostGone()
        break
      case 'rematch':
        if (msg.to === this.clientId && msg.roomId === this.ownRoomId && msg.from === this.guestId &&
            this.state?.winner != null) {
          this.startOnlineDuel(this.guestId, this.guestName)
        }
        break
      case 'error':
        if (msg.to === this.clientId && msg.error) {
          this.toast(msg.error, 'warn')
          this.connecting = false
          this.render()
        }
        break
      case 'denied':
        if (msg.to === this.clientId) {
          this.toast(msg.reason || '入室が拒否されました', 'warn')
          this.connecting = false
          this.returnToOwnRoom()
        }
        break
      case 'ping':
        if (msg.to === this.clientId && msg.from === this.guestId) this.lastGuestSeen = Date.now()
        break
      case 'rooms':
      case 'heartbeat':
        this.renderTopbar()
        if (this.drawerOpen) this.renderDrawerSafe()
        break
      default:
        break
    }
  }

  onJoin(msg) {
    if (msg.roomId !== this.ownRoomId) return
    if (this.role !== 'host') return
    if (!msg.from || msg.from === this.clientId) return
    if (this.guestId) {
      this.net.send({ type: 'denied', to: msg.from, roomId: msg.roomId, reason: '満室です' })
      return
    }
    const room = this.net.ownRoom()
    if (!room || !room.joinable || room.mode === 'away') {
      this.net.send({ type: 'denied', to: msg.from, roomId: msg.roomId, reason: '受付を終了しました' })
      return
    }
    this.guestId = msg.from
    this.guestName = String(msg.name || 'RIVAL').slice(0, 16)
    this.lastGuestSeen = Date.now()
    this.startOnlineDuel(this.guestId, this.guestName)
  }

  onStateMessage(msg) {
    if (msg.to !== this.clientId) return
    if (msg.roomId !== this.inRoomId) return
    if (this.role !== 'guest' && this.role !== 'guest-pending') return
    if (this.hostId && msg.from !== this.hostId) return
    if (!msg.state) return
    const wasConnecting = this.connecting
    clearTimeout(this.joinTimer)
    this.role = 'guest'
    this.mode = 'online'
    this.mySide = 1
    this.connecting = false
    this.hostGone = false
    this.hostId = msg.from
    this.hostName = msg.state.players?.[0]?.name || this.hostName
    this.state = msg.state
    this.sel = null
    if (this.state.winner == null) {
      this.resultReady = false
      clearTimeout(this.resultTimer)
    }
    this.render()
    playEvents(this, msg.events || [])
    if (this.state.winner != null) this.scheduleResult()
    if (wasConnecting) {
      this.toast('対人デュエルに接続しました', 'pvp', 3000)
      sfx(this, 'turn')
    }
  }

  onGuestAction(msg) {
    if (msg.to !== this.clientId || msg.roomId !== this.ownRoomId) return
    if (!this.guestId || msg.from !== this.guestId) return
    if (!this.state || this.role !== 'host') return
    this.lastGuestSeen = Date.now()
    const res = applyAction(this.state, 1, msg.action)
    if (!res.ok) {
      this.net.send({ type: 'error', to: msg.from, error: res.error || '実行できません' })
      return
    }
    this.sel = null
    this.render()
    playEvents(this, res.events)
    this.afterLocal(res.events)
  }

  onGuestLeft() {
    if (!this.guestId) return
    const name = this.guestName
    this.guestId = null
    this.guestName = null
    this.hostId = this.clientId
    this.mode = 'cpu'
    this.role = 'host'
    this.mySide = 0
    this.lastGuestSeen = 0
    this.net.updateRoom(this.ownRoomId, {
      mode: 'cpu', joinable: true, guestId: null, guestName: null, hostName: this.name,
    })
    if (this.state && this.state.winner == null) {
      const p = this.state.players[1]
      p.name = 'CPU・デュエリスト'
      p.isCPU = true
      this.state.mode = 'cpu'
      this.render()
      if (this.state.active === 1) this.scheduleCPU()
      else clearTimeout(this.cpuTimer)
      this.toast(`${name || '相手'}が退出。CPUがデュエルを引き継ぎます。`, 'warn', 3800)
    } else {
      this.resultReady = true
      this.render()
      renderOverlay(this)
      this.toast(`${name || '相手'}が退出しました`, 'warn', 3200)
    }
  }

  handleHostGone() {
    if (this.hostGone) return
    this.hostGone = true
    this.connecting = false
    this.role = 'guest-left'
    this.clearTimers()
    this.render()
    this.toast('ホストが退出しました', 'warn', 4000)
  }

  watchConnections() {
    if (this.role === 'host' && this.guestId && this.state?.winner == null) {
      if (this.lastGuestSeen && Date.now() - this.lastGuestSeen > 75000) {
        this.toast('相手の接続が切れました', 'warn', 3600)
        this.onGuestLeft()
      }
    }
    if (this.role === 'guest' && !this.hostGone) {
      const host = this.net.list().find((r) => r.id === this.inRoomId)
      if (!host) this.handleHostGone()
    }
  }

  cleanup() {
    if (this.cleaned) return
    this.cleaned = true
    try {
      if ((this.role === 'guest' || this.role === 'guest-pending') && this.hostId) {
        this.net.send({ type: 'leave', roomId: this.inRoomId, from: this.clientId, name: this.name })
      }
      if (this.role === 'host' && this.guestId) {
        this.net.send({ type: 'hostLeft', roomId: this.ownRoomId, to: this.guestId })
      }
      this.net.destroy()
    } catch { /* ignore */ }
  }
}

