/* ============================================================
   DUEL 24 ZONES — core visual system
   All card "art" is CSS/typography only. No image assets.
   ============================================================ */

:root {
  --bg-0: #04030c;
  --bg-1: #08071a;
  --ink: #eaf6ff;
  --muted: #8b9bc4;
  --dim: #56648c;
  --cyan: #5ef2ff;
  --cyan-soft: rgba(94, 242, 255, 0.16);
  --magenta: #ff4ecd;
  --violet: #8b7bff;
  --gold: #ffd166;
  --red: #ff5570;
  --green: #5df2a0;
  --panel: rgba(10, 15, 38, 0.72);
  --panel-2: rgba(15, 22, 54, 0.82);
  --line: rgba(120, 180, 255, 0.14);
  --line-hot: rgba(94, 242, 255, 0.55);
  --card-w: clamp(40px, 5.1vw, 82px);
  --card-h: calc(var(--card-w) * 1.42);
  --gap: clamp(3px, 0.45vw, 7px);
  --radius: 10px;
  --font-jp: "Hiragino Kaku Gothic ProN", "Yu Gothic", "Meiryo", "Noto Sans JP", sans-serif;
  --font-display: "Arial Black", "Hiragino Sans", "Yu Gothic", sans-serif;
  --font-mono: "SFMono-Regular", "Consolas", "Roboto Mono", monospace;
}

* { box-sizing: border-box; }

html, body {
  height: 100%;
  margin: 0;
}

body {
  background: var(--bg-0);
  color: var(--ink);
  font-family: var(--font-jp);
  overflow: hidden;
  -webkit-tap-highlight-color: transparent;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

button, input { font-family: inherit; }
button { color: inherit; }
button:focus-visible, [role="button"]:focus-visible, input:focus-visible {
  outline: 2px solid var(--cyan);
  outline-offset: 2px;
}

::selection { background: var(--magenta); color: #120018; }

/* ───────────────────────── background ───────────────────────── */

#bg {
  position: fixed;
  inset: 0;
  z-index: 0;
  overflow: hidden;
  background:
    radial-gradient(120% 90% at 50% -10%, #171c4b 0%, #090820 42%, #04030c 78%),
    linear-gradient(180deg, #060514 0%, #04030c 100%);
}

.orb {
  position: absolute;
  border-radius: 50%;
  filter: blur(70px);
  opacity: 0.5;
  animation: orbFloat 18s ease-in-out infinite alternate;
}
.orb-a {
  width: 46vw; height: 46vw;
  left: -14vw; top: -12vw;
  background: radial-gradient(circle, rgba(94, 242, 255, 0.42), transparent 66%);
}
.orb-b {
  width: 52vw; height: 52vw;
  right: -18vw; top: 8vh;
  background: radial-gradient(circle, rgba(255, 78, 205, 0.3), transparent 64%);
  animation-delay: -6s;
}
.orb-c {
  width: 44vw; height: 44vw;
  left: 28vw; bottom: -28vw;
  background: radial-gradient(circle, rgba(139, 123, 255, 0.32), transparent 66%);
  animation-delay: -11s;
}
.grid-floor {
  position: absolute;
  left: -20%;
  right: -20%;
  bottom: -26%;
  height: 70%;
  background-image:
    linear-gradient(rgba(94, 242, 255, 0.16) 1px, transparent 1px),
    linear-gradient(90deg, rgba(94, 242, 255, 0.12) 1px, transparent 1px);
  background-size: 60px 48px;
  transform: perspective(500px) rotateX(66deg);
  transform-origin: center bottom;
  mask-image: linear-gradient(180deg, transparent 5%, #000 62%, transparent 100%);
  animation: gridMove 8s linear infinite;
  opacity: 0.65;
}
.scan {
  position: absolute;
  inset: 0;
  background: repeating-linear-gradient(180deg, transparent 0 3px, rgba(255, 255, 255, 0.018) 3px 4px);
  pointer-events: none;
  mix-blend-mode: overlay;
}

/* ───────────────────────── shell ───────────────────────── */

#app {
  position: relative;
  z-index: 2;
  display: flex;
  flex-direction: column;
  height: 100dvh;
  width: min(1500px, 100%);
  margin: 0 auto;
  padding: 0 clamp(6px, 1.4vw, 20px);
}

#topbar {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: clamp(5px, 1vh, 12px) 2px 4px;
}

.brand {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 0;
  border: 0;
  background: none;
  text-align: left;
  cursor: pointer;
}
.brand-mark {
  position: relative;
  display: grid;
  place-items: center;
  width: clamp(34px, 3.4vw, 46px);
  height: clamp(34px, 3.4vw, 46px);
  border: 1px solid rgba(94, 242, 255, 0.65);
  border-radius: 10px;
  background:
    linear-gradient(145deg, rgba(94, 242, 255, 0.24), rgba(255, 78, 205, 0.12) 65%, transparent),
    #07091c;
  box-shadow: 0 0 20px rgba(94, 242, 255, 0.25), inset 0 0 18px rgba(94, 242, 255, 0.14);
  transform: skew(-6deg);
  overflow: hidden;
}
.brand-mark::after {
  content: "";
  position: absolute;
  inset: -50% -120%;
  background: linear-gradient(100deg, transparent 40%, rgba(255, 255, 255, 0.28) 50%, transparent 60%);
  animation: shine 7s ease-in-out infinite;
}
.brand-mark b {
  font-family: var(--font-mono);
  font-size: clamp(15px, 1.5vw, 21px);
  letter-spacing: -1px;
  color: var(--cyan);
  text-shadow: 0 0 12px rgba(94, 242, 255, 0.7);
}
.brand-mark i {
  position: absolute;
  right: 4px;
  bottom: 2px;
  font-style: normal;
  font-size: 7px;
  color: var(--magenta);
  opacity: 0.9;
}
.brand-text { display: flex; flex-direction: column; line-height: 1; }
.brand-title {
  font-family: var(--font-display);
  font-size: clamp(13px, 1.45vw, 20px);
  letter-spacing: 0.09em;
  font-weight: 900;
  color: #f4fbff;
  text-shadow: 0 0 16px rgba(94, 242, 255, 0.25);
}
.brand-title em {
  font-style: normal;
  color: var(--cyan);
  text-shadow: 0 0 16px rgba(94, 242, 255, 0.6);
}
.brand-sub {
  margin-top: 5px;
  font-family: var(--font-mono);
  font-size: clamp(5.5px, 0.55vw, 8px);
  letter-spacing: 0.22em;
  color: var(--muted);
  white-space: nowrap;
}

.top-right {
  display: flex;
  align-items: center;
  gap: 7px;
  min-width: 0;
}

.room-chip {
  display: flex;
  align-items: center;
  gap: 7px;
  height: 32px;
  padding: 0 10px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: rgba(9, 14, 36, 0.72);
  font-family: var(--font-mono);
  font-size: 9px;
  letter-spacing: 0.08em;
  color: #cfe8ff;
  cursor: pointer;
  white-space: nowrap;
  transition: border-color 0.2s, box-shadow 0.2s;
}
.room-chip:hover { border-color: var(--line-hot); box-shadow: 0 0 18px rgba(94, 242, 255, 0.14); }
.room-chip .dot {
  width: 6px; height: 6px;
  border-radius: 50%;
  background: var(--green);
  box-shadow: 0 0 8px var(--green);
  animation: dotPulse 2.2s ease-in-out infinite;
}
.room-chip[data-online="true"] .dot { background: var(--magenta); box-shadow: 0 0 8px var(--magenta); }
.chip-mode {
  padding: 2px 6px;
  border-radius: 999px;
  font-size: 7.5px;
  letter-spacing: 0.1em;
  background: rgba(94, 242, 255, 0.12);
  color: var(--cyan);
}
.chip-mode.mode-pvp { background: rgba(255, 78, 205, 0.16); color: var(--magenta); }
.chip-mode.mode-wait { background: rgba(255, 209, 102, 0.14); color: var(--gold); }
.chip-mode.mode-gone { background: rgba(255, 85, 112, 0.18); color: var(--red); }

.icon-btn {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  height: 32px;
  padding: 0 10px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: rgba(9, 14, 36, 0.72);
  font-family: var(--font-mono);
  font-size: 8px;
  letter-spacing: 0.1em;
  color: var(--muted);
  cursor: pointer;
  white-space: nowrap;
  transition: all 0.18s;
}
.icon-btn:hover { color: var(--ink); border-color: rgba(94, 242, 255, 0.4); }
.icon-btn .count {
  display: grid;
  place-items: center;
  min-width: 14px;
  height: 14px;
  padding: 0 3px;
  border-radius: 999px;
  background: var(--magenta);
  color: #fff;
  font-size: 8px;
  font-weight: 700;
}

/* ───────────────────────── table ───────────────────────── */

#table {
  flex: 1 1 auto;
  min-height: 0;
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: clamp(2px, 0.55vh, 8px);
  padding-bottom: max(4px, env(safe-area-inset-bottom));
}

.side {
  flex: 0 0 auto;
  width: max-content;
  max-width: 100%;
  margin: 0 auto;
}

.player-bar {
  display: flex;
  align-items: center;
  gap: clamp(6px, 0.7vw, 10px);
  width: 100%;
  min-height: clamp(36px, 4.4vh, 46px);
  margin-bottom: var(--gap);
  padding: 3px clamp(6px, 0.7vw, 10px);
  border: 1px solid var(--line);
  border-radius: 9px;
  background: linear-gradient(90deg, rgba(11, 17, 43, 0.86), rgba(8, 12, 31, 0.6));
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.04);
  position: relative;
  overflow: hidden;
}
.player-bar::before {
  content: "";
  position: absolute;
  inset: 0 auto 0 0;
  width: 3px;
  background: linear-gradient(180deg, var(--cyan), transparent);
  opacity: 0.6;
}
.player-bar.opponent::before { background: linear-gradient(180deg, var(--magenta), transparent); }
.player-bar.is-active { border-color: rgba(94, 242, 255, 0.32); }
.player-bar.opponent.is-active { border-color: rgba(255, 78, 205, 0.32); }

.avatar {
  position: relative;
  flex: 0 0 auto;
  display: grid;
  place-items: center;
  width: clamp(26px, 2.7vw, 34px);
  height: clamp(26px, 2.7vw, 34px);
  border-radius: 50%;
  background: radial-gradient(circle at 35% 30%, rgba(94, 242, 255, 0.32), rgba(10, 18, 46, 0.9));
  border: 1px solid rgba(94, 242, 255, 0.4);
  font-size: clamp(11px, 1vw, 14px);
  font-weight: 800;
  color: #dffaff;
}
.opponent .avatar {
  background: radial-gradient(circle at 35% 30%, rgba(255, 78, 205, 0.32), rgba(24, 10, 38, 0.9));
  border-color: rgba(255, 78, 205, 0.4);
  color: #ffe0f7;
}
.avatar.low { animation: lowPulse 1.2s ease-in-out infinite; }
.avatar-ring {
  position: absolute;
  inset: -4px;
  border-radius: 50%;
  border: 1px dashed rgba(94, 242, 255, 0.28);
  animation: spinSlow 16s linear infinite;
}
.opponent .avatar-ring { border-color: rgba(255, 78, 205, 0.3); }

.p-main { flex: 1 1 auto; min-width: 0; }
.p-name-row { display: flex; align-items: center; gap: 5px; min-width: 0; margin-bottom: 3px; }
.p-name {
  font-size: clamp(9px, 0.85vw, 12px);
  font-weight: 700;
  letter-spacing: 0.03em;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.p-badge {
  flex: 0 0 auto;
  padding: 1px 5px;
  border-radius: 3px;
  font-family: var(--font-mono);
  font-size: 6.5px;
  letter-spacing: 0.1em;
}
.p-badge.you { background: rgba(94, 242, 255, 0.18); color: var(--cyan); }
.p-badge.cpu { background: rgba(255, 209, 102, 0.15); color: var(--gold); }
.p-badge.rival { background: rgba(255, 78, 205, 0.16); color: var(--magenta); }
.p-badge.active {
  background: rgba(93, 242, 160, 0.14);
  color: var(--green);
  animation: dotPulse 2s infinite;
}
.p-badge.ex { background: rgba(139, 123, 255, 0.16); color: #b9aeff; }

.lp-block { min-width: 0; }
.lp-top { display: flex; align-items: baseline; justify-content: space-between; gap: 8px; }
.lp-label {
  font-family: var(--font-mono);
  font-size: clamp(5px, 0.48vw, 7px);
  letter-spacing: 0.18em;
  color: var(--dim);
}
.lp-num {
  font-family: var(--font-mono);
  font-size: clamp(11px, 1.1vw, 16px);
  font-weight: 700;
  color: #dffaff;
  letter-spacing: 0.03em;
  font-variant-numeric: tabular-nums;
  text-shadow: 0 0 10px rgba(94, 242, 255, 0.3);
}
.lp-num.low { color: var(--red); text-shadow: 0 0 12px rgba(255, 85, 112, 0.6); }
.lp-track {
  position: relative;
  height: clamp(4px, 0.55vh, 6px);
  margin-top: 2px;
  border-radius: 99px;
  background: rgba(255, 255, 255, 0.07);
  overflow: hidden;
  border: 1px solid rgba(255, 255, 255, 0.04);
}
.lp-fill {
  display: block;
  height: 100%;
  border-radius: 99px;
  background: linear-gradient(90deg, var(--cyan), #5b9cff 55%, var(--magenta));
  box-shadow: 0 0 8px rgba(94, 242, 255, 0.5);
  transition: width 0.55s cubic-bezier(0.2, 0.8, 0.2, 1);
}
.lp-fill.low { background: linear-gradient(90deg, #ff7b4d, var(--red)); box-shadow: 0 0 10px rgba(255, 85, 112, 0.6); }
.lp-ticks {
  position: absolute;
  inset: 0;
  background: repeating-linear-gradient(90deg, transparent 0 calc(10% - 1px), rgba(0, 0, 0, 0.28) calc(10% - 1px) 10%);
  pointer-events: none;
}

.hand-stack {
  position: relative;
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  min-width: 26px;
  height: 26px;
  padding-right: 2px;
}
.hand-stack .mini-back {
  width: 12px;
  height: 18px;
  margin-left: -7px;
  border: 1px solid rgba(139, 123, 255, 0.55);
  border-radius: 2px;
  background:
    repeating-linear-gradient(45deg, rgba(139, 123, 255, 0.25) 0 2px, transparent 2px 4px),
    #0d0b24;
  box-shadow: 0 0 5px rgba(139, 123, 255, 0.2);
}
.hand-stack .mini-back:first-child { margin-left: 0; }
.hand-stack b {
  margin-left: 5px;
  font-family: var(--font-mono);
  font-size: 9px;
  color: var(--muted);
}
.hand-stack.self-hand { gap: 4px; }
.hand-stack.self-hand span { font-size: 7px; color: var(--dim); }
.hand-stack.self-hand b { margin-left: 0; color: var(--ink); }

.bar-meta {
  flex: 0 0 auto;
  display: flex;
  flex-direction: column;
  gap: 1px;
  padding-left: 8px;
  border-left: 1px solid var(--line);
  font-family: var(--font-mono);
  font-size: 6.5px;
  letter-spacing: 0.06em;
  color: var(--dim);
  white-space: nowrap;
}
.bar-meta b { color: var(--muted); }

/* ───────────────────────── board ───────────────────────── */

.board-grid {
  display: grid;
  grid-template-columns: var(--card-w) repeat(5, var(--card-w)) calc(var(--card-w) * 0.92);
  grid-template-rows: var(--card-h) var(--card-h);
  gap: var(--gap);
  width: max-content;
  margin: 0 auto;
}

.zone {
  position: relative;
  width: var(--card-w);
  height: var(--card-h);
  border: 1px solid rgba(94, 242, 255, 0.14);
  border-radius: 8px;
  background:
    linear-gradient(160deg, rgba(94, 242, 255, 0.055), transparent 45%),
    rgba(8, 13, 34, 0.62);
  box-shadow: inset 0 0 16px rgba(94, 242, 255, 0.03), inset 0 0 0 1px rgba(255, 255, 255, 0.018);
  overflow: hidden;
  transition: border-color 0.2s, box-shadow 0.2s, background 0.2s;
  cursor: pointer;
}
.opponent .zone {
  border-color: rgba(255, 78, 205, 0.14);
  background:
    linear-gradient(160deg, rgba(255, 78, 205, 0.045), transparent 45%),
    rgba(13, 8, 30, 0.62);
}
.zone:hover { border-color: rgba(94, 242, 255, 0.4); }
.opponent .zone:hover { border-color: rgba(255, 78, 205, 0.4); }
.zone.filled { border-color: rgba(94, 242, 255, 0.3); }
.opponent .zone.filled { border-color: rgba(255, 78, 205, 0.28); }
.zone-empty { cursor: default; }

.zone-num {
  position: absolute;
  top: 2px;
  right: 3px;
  z-index: 3;
  font-family: var(--font-mono);
  font-size: 5.5px;
  color: var(--ink);
  opacity: 0.22;
  pointer-events: none;
}
.zone-label {
  position: absolute;
  bottom: 2px;
  left: 3px;
  z-index: 3;
  font-family: var(--font-mono);
  font-size: 5.5px;
  letter-spacing: 0.1em;
  color: var(--ink);
  opacity: 0.24;
  pointer-events: none;
}
.zone-plus {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  font-family: var(--font-mono);
  font-size: clamp(9px, 1vw, 13px);
  color: rgba(94, 242, 255, 0.16);
  letter-spacing: 0.1em;
  transition: color 0.2s, transform 0.2s;
}
.zone:hover .zone-plus { color: rgba(94, 242, 255, 0.42); transform: scale(1.12); }
.zone-emz .zone-plus, .zone-field .zone-plus { font-size: 6px; opacity: 0.6; }
.zone .card { position: absolute; inset: 0; width: 100%; height: 100%; z-index: 2; }

.zone.hl-place {
  border-color: var(--cyan);
  background: linear-gradient(160deg, rgba(94, 242, 255, 0.2), rgba(94, 242, 255, 0.04));
  box-shadow: 0 0 18px rgba(94, 242, 255, 0.4), inset 0 0 18px rgba(94, 242, 255, 0.12);
  animation: targetPulse 1.2s ease-in-out infinite;
}
.zone.hl-target {
  border-color: var(--red);
  box-shadow: 0 0 18px rgba(255, 85, 112, 0.55), inset 0 0 18px rgba(255, 85, 112, 0.15);
  animation: targetPulse 0.9s ease-in-out infinite;
}
.zone.hl-target .card { filter: saturate(1.2) brightness(1.06); }
.zone.hl-attacker {
  border-color: var(--gold);
  box-shadow: 0 0 18px rgba(255, 209, 102, 0.45), inset 0 0 14px rgba(255, 209, 102, 0.12);
}
.zone.hl-info { border-color: rgba(139, 123, 255, 0.8); box-shadow: 0 0 14px rgba(139, 123, 255, 0.35); }
.zone.can-attack::after {
  content: "⚔";
  position: absolute;
  top: 3px;
  left: 3px;
  z-index: 4;
  font-size: 8px;
  color: var(--gold);
  text-shadow: 0 0 8px rgba(255, 209, 102, 0.8);
  animation: dotPulse 1.3s infinite;
}
.zone.emz-ready {
  border-color: rgba(139, 123, 255, 0.65);
  box-shadow: 0 0 14px rgba(139, 123, 255, 0.3);
}
.zone.emz-ready .zone-plus { color: #b9aeff; opacity: 0.9; animation: dotPulse 1.5s infinite; }

.zone.zone-flash { animation: zoneFlash 0.85s ease-out; }
.zone.zone-special { animation: zoneSpecial 0.95s ease-out; }
.zone.zone-set { animation: zoneSet 0.7s ease-out; }
.zone.zone-trap { animation: zoneTrap 0.8s ease-out; }
.zone.zone-spell { animation: zoneFlash 0.8s ease-out; }
.zone.zone-field { animation: zoneSpecial 1s ease-out; }

/* piles */
.piles {
  grid-column: 7;
  grid-row: 1 / 3;
  display: grid;
  grid-template-columns: 1fr 1fr;
  grid-template-rows: 1fr 1fr;
  gap: var(--gap);
}
.pile {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 0;
  min-width: 0;
  padding: 1px;
  border: 1px solid rgba(139, 123, 255, 0.16);
  border-radius: 6px;
  background:
    linear-gradient(160deg, rgba(139, 123, 255, 0.1), transparent 55%),
    rgba(9, 10, 30, 0.72);
  cursor: pointer;
  overflow: hidden;
  transition: border-color 0.2s, box-shadow 0.2s;
}
.pile:hover { border-color: rgba(139, 123, 255, 0.55); box-shadow: 0 0 12px rgba(139, 123, 255, 0.2); }
.pile-label {
  font-family: var(--font-mono);
  font-size: 5.5px;
  letter-spacing: 0.08em;
  color: var(--dim);
}
.pile b {
  font-family: var(--font-mono);
  font-size: clamp(9px, 0.9vw, 12px);
  line-height: 1.1;
  color: #d9e4ff;
}
.pile i {
  font-style: normal;
  font-size: 5px;
  color: var(--dim);
  opacity: 0.7;
  white-space: nowrap;
}
.pile-extra.ready {
  border-color: rgba(255, 78, 205, 0.6);
  box-shadow: 0 0 14px rgba(255, 78, 205, 0.3);
}
.pile-extra.ready i { color: var(--magenta); opacity: 1; animation: dotPulse 1.4s infinite; }
.pile-gy { border-color: rgba(255, 85, 112, 0.16); }
.pile-void { border-color: rgba(94, 242, 255, 0.12); }

/* ───────────────────────── cards ───────────────────────── */

.card {
  --frame: #6c8cff;
  --art-a: #1a2454;
  --art-b: #070a1d;
  position: relative;
  display: flex;
  flex-direction: column;
  width: 100%;
  height: 100%;
  padding: 3px;
  border: 1px solid color-mix(in srgb, var(--frame) 58%, transparent);
  border-radius: 7px;
  background:
    linear-gradient(155deg, color-mix(in srgb, var(--frame) 34%, #0a0d21) 0%, #090b1c 42%, #050611 100%);
  box-shadow:
    0 3px 10px rgba(0, 0, 0, 0.55),
    inset 0 0 0 1px rgba(255, 255, 255, 0.05),
    0 0 12px color-mix(in srgb, var(--frame) 24%, transparent);
  overflow: hidden;
  transform-origin: center;
  animation: cardFloat 5.2s ease-in-out infinite;
  animation-delay: calc(var(--i, 0) * -0.62s);
  user-select: none;
}

.rarity-ur { box-shadow: 0 3px 12px rgba(0, 0, 0, 0.55), inset 0 0 0 1px rgba(255, 209, 102, 0.25), 0 0 14px color-mix(in srgb, var(--frame) 38%, transparent); }
.rarity-ur::after {
  content: "";
  position: absolute;
  inset: -40% -80%;
  background: linear-gradient(100deg, transparent 42%, rgba(255, 255, 255, 0.22) 50%, transparent 58%);
  animation: shine 5.5s ease-in-out infinite;
  pointer-events: none;
}
.rarity-sr::after {
  content: "";
  position: absolute;
  inset: -40% -80%;
  background: linear-gradient(100deg, transparent 43%, rgba(255, 255, 255, 0.12) 50%, transparent 57%);
  animation: shine 7.5s ease-in-out infinite;
  pointer-events: none;
}

.type-spell { --frame: #24d6ad; }
.type-trap { --frame: #c161ff; }

.attr-light { --art-a: #ffe6a3; --art-b: #8a5a13; }
.attr-dark { --art-a: #b48cff; --art-b: #2c1357; }
.attr-fire { --art-a: #ff9a5c; --art-b: #701a17; }
.attr-water { --art-a: #7cd8ff; --art-b: #0a3960; }
.attr-wind { --art-a: #8dffc4; --art-b: #0e4b3a; }
.attr-earth { --art-a: #d9b27c; --art-b: #4b2f17; }
.attr-spell { --art-a: #7dffd8; --art-b: #073d35; }
.attr-trap { --art-a: #e0a8ff; --art-b: #3d145a; }

.card-sheen {
  position: absolute;
  inset: 0;
  background: linear-gradient(115deg, transparent 30%, rgba(255, 255, 255, 0.07) 46%, transparent 58%);
  background-size: 250% 250%;
  animation: sheen 6.5s ease-in-out infinite;
  pointer-events: none;
  z-index: 1;
}

.card-head {
  position: relative;
  z-index: 2;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 2px;
  padding: 1px 2px 2px;
  border-bottom: 1px solid color-mix(in srgb, var(--frame) 25%, transparent);
}
.card-name {
  font-size: clamp(5.4px, 0.52vw, 8px);
  font-weight: 700;
  line-height: 1.08;
  color: #f2f9ff;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
  text-shadow: 0 1px 2px #000;
  letter-spacing: -0.01em;
}
.card-tag {
  flex: 0 0 auto;
  font-family: var(--font-mono);
  font-size: clamp(4px, 0.4vw, 6px);
  color: color-mix(in srgb, var(--frame) 80%, white);
  opacity: 0.9;
  padding-top: 1px;
}

.card-art {
  position: relative;
  z-index: 2;
  flex: 1 1 auto;
  display: grid;
  place-items: center;
  min-height: 0;
  margin: 2px 0;
  border-radius: 4px;
  background:
    radial-gradient(circle at 50% 45%, color-mix(in srgb, var(--art-a) 64%, transparent) 0%, transparent 62%),
    linear-gradient(160deg, var(--art-a), var(--art-b) 78%);
  overflow: hidden;
  box-shadow: inset 0 0 10px rgba(0, 0, 0, 0.45);
}
.card-art::before {
  content: "";
  position: absolute;
  inset: 0;
  background-image:
    linear-gradient(rgba(255, 255, 255, 0.06) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255, 255, 255, 0.05) 1px, transparent 1px);
  background-size: 9px 9px;
  mask-image: radial-gradient(circle, #000 20%, transparent 78%);
  opacity: 0.55;
}
.art-glyph {
  position: relative;
  z-index: 2;
  font-family: var(--font-display);
  font-size: calc(var(--card-w) * 0.33);
  line-height: 1;
  color: rgba(255, 255, 255, 0.95);
  text-shadow: 0 2px 5px rgba(0, 0, 0, 0.65), 0 0 14px color-mix(in srgb, var(--art-a) 80%, transparent);
  transform: translateZ(0);
}
.art-orbit {
  position: absolute;
  width: 76%;
  aspect-ratio: 1;
  border: 1px solid rgba(255, 255, 255, 0.28);
  border-radius: 50%;
  border-left-color: transparent;
  border-bottom-color: transparent;
  animation: spinSlow 9s linear infinite;
  opacity: 0.6;
}
.art-attr {
  position: absolute;
  right: 2px;
  bottom: 1px;
  z-index: 2;
  font-size: clamp(4px, 0.38vw, 5.5px);
  color: rgba(255, 255, 255, 0.65);
  text-shadow: 0 1px 2px #000;
}

.card-foot {
  position: relative;
  z-index: 2;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 2px;
  min-height: clamp(9px, 1vw, 13px);
  padding: 1px 2px 0;
  border-top: 1px solid color-mix(in srgb, var(--frame) 22%, transparent);
  font-family: var(--font-mono);
  font-size: clamp(4.4px, 0.44vw, 6.4px);
  color: #cfe1ff;
}
.stat { display: flex; align-items: baseline; gap: 1px; white-space: nowrap; }
.stat i { font-style: normal; font-size: 0.78em; opacity: 0.55; }
.stat b { font-size: 1.05em; font-weight: 700; }
.stat.buffed b { color: var(--green); text-shadow: 0 0 6px rgba(93, 242, 160, 0.5); }
.spell-kind { letter-spacing: 0.08em; color: color-mix(in srgb, var(--frame) 82%, white); }
.spell-mark { opacity: 0.6; }

.pos-badge, .buff-badge, .extra-badge {
  position: absolute;
  z-index: 5;
  padding: 1px 3px;
  border-radius: 3px;
  font-family: var(--font-mono);
  font-size: clamp(4px, 0.4vw, 5.5px);
  font-weight: 700;
  letter-spacing: 0.06em;
  pointer-events: none;
}
.pos-badge { right: 3px; top: 3px; background: rgba(10, 30, 60, 0.88); color: #9fdcff; border: 1px solid rgba(94, 242, 255, 0.4); }
.buff-badge { left: 3px; bottom: 10px; background: rgba(10, 50, 34, 0.9); color: var(--green); border: 1px solid rgba(93, 242, 160, 0.4); }
.extra-badge { right: 3px; bottom: 10px; background: rgba(50, 10, 70, 0.9); color: #e5b8ff; border: 1px solid rgba(193, 97, 255, 0.45); }

/* face-down card back */
.card-back {
  padding: 0;
  background:
    radial-gradient(circle at 50% 40%, rgba(139, 123, 255, 0.26), transparent 58%),
    repeating-linear-gradient(45deg, rgba(139, 123, 255, 0.13) 0 2px, transparent 2px 7px),
    repeating-linear-gradient(-45deg, rgba(94, 242, 255, 0.08) 0 2px, transparent 2px 9px),
    linear-gradient(160deg, #171240, #070718 70%);
  border-color: rgba(139, 123, 255, 0.5);
  display: grid;
  place-items: center;
}
.back-lines {
  position: absolute;
  inset: 3px;
  border: 1px solid rgba(139, 123, 255, 0.28);
  border-radius: 4px;
}
.back-lines::before, .back-lines::after {
  content: "";
  position: absolute;
  left: 50%;
  top: 50%;
  width: 130%;
  height: 1px;
  background: rgba(139, 123, 255, 0.2);
  transform: translate(-50%, -50%) rotate(45deg);
}
.back-lines::after { transform: translate(-50%, -50%) rotate(-45deg); }
.back-mark {
  position: relative;
  z-index: 2;
  font-family: var(--font-mono);
  font-size: calc(var(--card-w) * 0.28);
  font-weight: 800;
  color: rgba(196, 186, 255, 0.9);
  text-shadow: 0 0 12px rgba(139, 123, 255, 0.75);
}
.back-sub {
  position: absolute;
  bottom: 12%;
  z-index: 2;
  font-family: var(--font-mono);
  font-size: 5px;
  letter-spacing: 0.3em;
  color: rgba(196, 186, 255, 0.6);
}
.back-set {
  position: absolute;
  top: 3px;
  right: 3px;
  z-index: 2;
  font-family: var(--font-mono);
  font-size: 4.5px;
  color: rgba(196, 186, 255, 0.55);
}

/* ───────────────────────── center bar ───────────────────────── */

.center-bar {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  width: min(100%, 1120px);
  margin: 1px auto;
  padding: clamp(3px, 0.6vh, 6px) clamp(6px, 0.8vw, 12px);
  border-top: 1px solid rgba(94, 242, 255, 0.14);
  border-bottom: 1px solid rgba(255, 78, 205, 0.12);
  background: linear-gradient(90deg, transparent, rgba(10, 16, 42, 0.72) 15%, rgba(10, 16, 42, 0.72) 85%, transparent);
}
.turn-cluster { display: flex; align-items: center; gap: clamp(5px, 0.6vw, 9px); flex: 0 0 auto; }
.turn-badge {
  display: flex;
  align-items: baseline;
  gap: 3px;
  padding: 2px 6px;
  border: 1px solid rgba(94, 242, 255, 0.35);
  border-radius: 5px;
  background: rgba(94, 242, 255, 0.07);
  box-shadow: inset 0 0 10px rgba(94, 242, 255, 0.08);
}
.turn-badge span { font-family: var(--font-mono); font-size: 5.5px; letter-spacing: 0.1em; color: var(--muted); }
.turn-badge b { font-family: var(--font-mono); font-size: clamp(12px, 1.25vw, 17px); color: var(--cyan); line-height: 1; }
.turn-info { display: flex; flex-direction: column; gap: 1px; }
.turn-status {
  font-family: var(--font-mono);
  font-size: clamp(6px, 0.6vw, 8px);
  letter-spacing: 0.12em;
  color: var(--muted);
}
.turn-status.mine { color: var(--cyan); text-shadow: 0 0 10px rgba(94, 242, 255, 0.45); }
.turn-status.theirs { color: var(--magenta); }
.turn-status.dead { color: var(--gold); }
.phase-pips { display: flex; gap: 3px; }
.pip {
  font-style: normal;
  font-family: var(--font-mono);
  font-size: 5.5px;
  letter-spacing: 0.08em;
  padding: 1px 4px;
  border-radius: 2px;
  color: var(--dim);
  background: rgba(255, 255, 255, 0.03);
}
.pip.on { color: #061018; background: var(--cyan); box-shadow: 0 0 10px rgba(94, 242, 255, 0.5); }

.center-mid { flex: 1 1 auto; min-width: 0; text-align: center; }
.center-hint {
  margin: 0;
  font-size: clamp(8px, 0.78vw, 11px);
  font-weight: 700;
  letter-spacing: 0.02em;
  color: #d9ecff;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.center-log {
  margin: 1px 0 0;
  font-family: var(--font-mono);
  font-size: clamp(5.5px, 0.52vw, 7.5px);
  color: var(--dim);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.center-log span {
  margin-right: 5px;
  color: var(--cyan);
  opacity: 0.6;
  letter-spacing: 0.1em;
}
.center-log.tone-p0, .center-log.tone-p1 { color: var(--muted); }

.center-actions { display: flex; align-items: center; gap: 4px; flex: 0 0 auto; }
.btn {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  border: 1px solid rgba(94, 242, 255, 0.25);
  border-radius: 6px;
  background: rgba(9, 16, 40, 0.82);
  color: #d6eeff;
  font-family: var(--font-mono);
  font-size: clamp(6.5px, 0.62vw, 8.5px);
  font-weight: 700;
  letter-spacing: 0.08em;
  padding: clamp(4px, 0.5vh, 6px) clamp(6px, 0.7vw, 11px);
  cursor: pointer;
  white-space: nowrap;
  transition: transform 0.15s, border-color 0.18s, box-shadow 0.18s, background 0.18s;
}
.btn:hover:not(:disabled) { border-color: var(--cyan); box-shadow: 0 0 14px rgba(94, 242, 255, 0.22); transform: translateY(-1px); }
.btn:active:not(:disabled) { transform: translateY(0) scale(0.98); }
.btn:disabled { opacity: 0.32; cursor: not-allowed; }
.btn-battle {
  border-color: rgba(255, 78, 205, 0.45);
  background: linear-gradient(180deg, rgba(255, 78, 205, 0.24), rgba(80, 10, 60, 0.5));
  color: #ffd9f5;
}
.btn-battle:hover:not(:disabled) { border-color: var(--magenta); box-shadow: 0 0 16px rgba(255, 78, 205, 0.35); }
.btn-extra { color: #cbbfff; border-color: rgba(139, 123, 255, 0.32); }
.btn-extra.has-ex { border-color: rgba(139, 123, 255, 0.7); box-shadow: 0 0 12px rgba(139, 123, 255, 0.28); }
.btn-end { color: var(--muted); }
.btn-primary {
  border-color: rgba(94, 242, 255, 0.55);
  background: linear-gradient(180deg, rgba(94, 242, 255, 0.24), rgba(10, 40, 60, 0.65));
  color: #eaffff;
}
.btn-ghost { background: rgba(255, 255, 255, 0.04); color: var(--muted); }
.btn-danger { border-color: rgba(255, 85, 112, 0.4); color: #ffb6c1; background: rgba(80, 10, 25, 0.35); }
.btn-sm { padding: 5px 8px; font-size: 7.5px; }

/* ───────────────────────── hand + info ───────────────────────── */

.hand-area {
  flex: 0 0 auto;
  display: flex;
  flex-direction: column;
  gap: clamp(3px, 0.5vh, 6px);
  width: min(100%, 1240px);
  margin: 1px auto 0;
}

.info-panel {
  display: flex;
  align-items: stretch;
  justify-content: space-between;
  gap: 10px;
  min-height: clamp(42px, 6vh, 56px);
  padding: clamp(4px, 0.6vh, 7px) clamp(7px, 0.9vw, 14px);
  border: 1px solid var(--line);
  border-radius: 8px;
  background:
    linear-gradient(90deg, rgba(94, 242, 255, 0.035), transparent 55%, rgba(255, 78, 205, 0.025)),
    rgba(8, 12, 32, 0.66);
  overflow: hidden;
}
.info-card { flex: 1 1 auto; min-width: 0; }
.info-title { display: flex; align-items: center; gap: 6px; flex-wrap: wrap; }
.info-title b { font-size: clamp(9px, 0.85vw, 12px); color: #f2fbff; letter-spacing: 0.01em; }
.info-type {
  font-family: var(--font-mono);
  font-size: clamp(5.5px, 0.5vw, 7px);
  color: var(--dim);
  letter-spacing: 0.06em;
}
.info-stat {
  font-family: var(--font-mono);
  font-size: clamp(5.5px, 0.52vw, 7.5px);
  color: var(--muted);
  padding: 1px 5px;
  border: 1px solid var(--line);
  border-radius: 3px;
}
.info-stat b { color: var(--ink); }
.info-text {
  margin: 3px 0 0;
  font-size: clamp(7px, 0.68vw, 9.5px);
  line-height: 1.35;
  color: var(--muted);
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.rarity {
  flex: 0 0 auto;
  padding: 1px 4px;
  border-radius: 2px;
  font-family: var(--font-mono);
  font-size: 5.5px;
  font-weight: 700;
  letter-spacing: 0.08em;
  border: 1px solid currentColor;
}
.rarity-ur { color: var(--gold); }
.rarity-sr { color: #a8e9ff; }
.rarity-r { color: #c4b6ff; }
.rarity-n { color: var(--dim); }

.info-actions {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  gap: 4px;
  align-self: center;
  flex-wrap: wrap;
  justify-content: flex-end;
}
.info-tip { font-size: 7px; color: var(--dim); letter-spacing: 0.02em; margin-right: 2px; }
.info-empty {
  display: flex;
  align-items: center;
  gap: 9px;
  width: 100%;
  min-width: 0;
}
.info-orb {
  flex: 0 0 auto;
  width: clamp(24px, 2.6vw, 34px);
  height: clamp(24px, 2.6vw, 34px);
  border-radius: 50%;
  background:
    radial-gradient(circle at 35% 30%, rgba(94, 242, 255, 0.5), transparent 55%),
    conic-gradient(from 0deg, rgba(94, 242, 255, 0.2), rgba(255, 78, 205, 0.25), rgba(94, 242, 255, 0.2));
  border: 1px solid rgba(94, 242, 255, 0.28);
  animation: spinSlow 10s linear infinite;
  box-shadow: 0 0 16px rgba(94, 242, 255, 0.15);
}
.info-empty b {
  display: block;
  font-family: var(--font-mono);
  font-size: clamp(7px, 0.65vw, 9px);
  letter-spacing: 0.12em;
  color: var(--cyan);
  margin-bottom: 1px;
}
.info-empty p {
  margin: 0;
  font-size: clamp(7px, 0.66vw, 9px);
  color: var(--muted);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: min(60vw, 700px);
}
.info-zones {
  margin-left: auto;
  font-family: var(--font-mono);
  font-size: 7px;
  letter-spacing: 0.14em;
  color: var(--dim);
  border: 1px solid var(--line);
  border-radius: 3px;
  padding: 2px 5px;
  white-space: nowrap;
}

.hand-bar {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}
.hand-meta {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 0 3px;
  font-family: var(--font-mono);
  font-size: 6px;
  color: var(--dim);
  letter-spacing: 0.08em;
}
.hand-title { color: var(--muted); }
.hand-title b { color: var(--ink); font-size: 8px; }
.hand-sub { opacity: 0.8; }
.turn-mini {
  margin-left: auto;
  color: var(--dim);
  letter-spacing: 0.14em;
}
.turn-mini.mine { color: var(--cyan); animation: dotPulse 2.2s infinite; }
.hand-scroll {
  display: flex;
  align-items: flex-end;
  gap: clamp(4px, 0.5vw, 8px);
  min-height: calc(var(--card-w) * 1.42 + 10px);
  padding: 8px 4px 2px;
  overflow-x: auto;
  overflow-y: hidden;
  scrollbar-width: thin;
  scrollbar-color: rgba(94, 242, 255, 0.25) transparent;
  scroll-behavior: smooth;
  -webkit-overflow-scrolling: touch;
}
.hand-scroll::-webkit-scrollbar { height: 4px; }
.hand-scroll::-webkit-scrollbar-thumb { background: rgba(94, 242, 255, 0.25); border-radius: 99px; }
.hand-card {
  flex: 0 0 auto;
  width: clamp(62px, 7vw, 92px);
  aspect-ratio: 1 / 1.42;
  padding: 0;
  border: 0;
  background: none;
  cursor: pointer;
  position: relative;
  transition: transform 0.18s cubic-bezier(0.2, 0.8, 0.2, 1), filter 0.18s;
  transform-origin: center bottom;
  filter: drop-shadow(0 3px 6px rgba(0, 0, 0, 0.5));
}
.hand-card:hover { transform: translateY(-10px) scale(1.04); z-index: 6; filter: drop-shadow(0 8px 14px rgba(94, 242, 255, 0.22)); }
.hand-card.selected { transform: translateY(-14px) scale(1.06); z-index: 7; }
.hand-card.selected .card { border-color: var(--cyan); box-shadow: 0 0 18px rgba(94, 242, 255, 0.55), inset 0 0 0 1px rgba(94, 242, 255, 0.4); }
.hand-card.placing .card { border-color: var(--gold); box-shadow: 0 0 18px rgba(255, 209, 102, 0.5); }
.hand-card .card { width: 100%; height: 100%; }
.hand-card .card-name { font-size: clamp(6.5px, 0.68vw, 9px); }
.hand-card .art-glyph { font-size: calc(clamp(62px, 7vw, 92px) * 0.34); }
.hand-card .card-foot { font-size: clamp(5px, 0.5vw, 7px); }
.hand-empty {
  font-family: var(--font-mono);
  font-size: 7px;
  color: var(--dim);
  letter-spacing: 0.1em;
  padding: 20px;
}

/* ───────────────────────── FX ───────────────────────── */

.fx-layer {
  position: fixed;
  inset: 0;
  z-index: 90;
  pointer-events: none;
  overflow: hidden;
}
.fx-float {
  position: fixed;
  z-index: 95;
  font-family: var(--font-mono);
  font-size: clamp(15px, 2vw, 26px);
  font-weight: 800;
  letter-spacing: 0.02em;
  text-shadow: 0 2px 10px rgba(0, 0, 0, 0.8);
  white-space: nowrap;
}
.fx-float.bad { color: var(--red); text-shadow: 0 0 16px rgba(255, 85, 112, 0.8), 0 2px 8px #000; }
.fx-float.good { color: var(--green); text-shadow: 0 0 16px rgba(93, 242, 160, 0.8), 0 2px 8px #000; }
.fx-slash {
  position: fixed;
  z-index: 96;
  width: 130px;
  height: 130px;
  transform: translate(-50%, -50%);
}
.fx-slash i {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 120%;
  height: 3px;
  background: linear-gradient(90deg, transparent, #fff 25%, var(--cyan) 50%, transparent 90%);
  box-shadow: 0 0 14px var(--cyan);
  transform: translate(-50%, -50%) rotate(38deg);
}
.fx-slash i:nth-child(2) { transform: translate(-50%, -50%) rotate(-38deg); height: 2px; opacity: 0.85; }
.fx-slash.slash-direct i { background: linear-gradient(90deg, transparent, #fff 25%, var(--magenta) 50%, transparent 90%); box-shadow: 0 0 14px var(--magenta); }
.fx-slash b {
  position: absolute;
  inset: 22%;
  border: 1px solid rgba(255, 255, 255, 0.65);
  border-radius: 50%;
  box-shadow: 0 0 24px var(--cyan);
}
.fx-burst {
  position: fixed;
  z-index: 95;
  width: 0;
  height: 0;
}
.fx-burst i {
  position: absolute;
  left: 0;
  top: 0;
  width: 36px;
  height: 2px;
  background: linear-gradient(90deg, var(--gold), transparent);
  transform-origin: left center;
  animation: burstOut 0.55s ease-out forwards;
}
.fx-burst i:nth-child(1) { transform: rotate(0deg); }
.fx-burst i:nth-child(2) { transform: rotate(60deg); }
.fx-burst i:nth-child(3) { transform: rotate(120deg); }
.fx-burst i:nth-child(4) { transform: rotate(180deg); }
.fx-burst i:nth-child(5) { transform: rotate(240deg); }
.fx-burst i:nth-child(6) { transform: rotate(300deg); }
.fx-flash {
  position: fixed;
  inset: 0;
  pointer-events: none;
  animation: flashFade 0.5s ease-out forwards;
  background: radial-gradient(circle at 50% 50%, rgba(94, 242, 255, 0.22), transparent 60%);
}
.fx-flash.hit { background: radial-gradient(circle at 50% 55%, rgba(255, 85, 112, 0.28), transparent 62%); }
.fx-flash.summon { background: radial-gradient(circle at 50% 55%, rgba(255, 209, 102, 0.2), transparent 60%); }
.fx-flash.trap { background: radial-gradient(circle at 50% 55%, rgba(193, 97, 255, 0.24), transparent 62%); }
.fx-flash.spell { background: radial-gradient(circle at 50% 55%, rgba(36, 214, 173, 0.22), transparent 62%); }
.fx-flash.win { background: radial-gradient(circle at 50% 50%, rgba(255, 209, 102, 0.3), transparent 65%); }
.fx-flash.lose { background: radial-gradient(circle at 50% 50%, rgba(255, 85, 112, 0.26), transparent 65%); }
.fx-flash.start, .fx-flash.phase { background: radial-gradient(circle at 50% 50%, rgba(94, 242, 255, 0.16), transparent 62%); }
.fx-ghost {
  position: fixed;
  z-index: 94;
  transform-origin: center;
  pointer-events: none;
}
.fx-ghost .card { width: 100%; height: 100%; animation: none; }

#app.shake { animation: appShake 0.36s cubic-bezier(0.36, 0.07, 0.19, 0.97); }

/* ───────────────────────── keyframes ───────────────────────── */

@keyframes cardFloat {
  0%, 100% { transform: translateY(0) rotate(0deg); }
  35% { transform: translateY(-1.6px) rotate(0.35deg); }
  70% { transform: translateY(0.8px) rotate(-0.25deg); }
}
@keyframes sheen {
  0%, 55% { background-position: 220% 0; }
  75%, 100% { background-position: -120% 0; }
}
@keyframes shine {
  0%, 62% { transform: translateX(-60%) skewX(-12deg); opacity: 0; }
  72% { opacity: 0.75; }
  86%, 100% { transform: translateX(150%) skewX(-12deg); opacity: 0; }
}
@keyframes spinSlow { to { transform: rotate(360deg); } }
@keyframes orbFloat {
  0% { transform: translate3d(0, 0, 0) scale(1); }
  100% { transform: translate3d(4vw, 5vh, 0) scale(1.12); }
}
@keyframes gridMove { to { background-position: 0 48px, 60px 0; } }
@keyframes dotPulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.35; }
}
@keyframes lowPulse {
  0%, 100% { box-shadow: 0 0 0 rgba(255, 85, 112, 0); }
  50% { box-shadow: 0 0 16px rgba(255, 85, 112, 0.65); }
}
@keyframes targetPulse {
  0%, 100% { filter: brightness(1); }
  50% { filter: brightness(1.35); }
}
@keyframes zoneFlash {
  0% { box-shadow: inset 0 0 0 1px rgba(94, 242, 255, 0.8), 0 0 28px rgba(94, 242, 255, 0.6); }
  100% { box-shadow: inset 0 0 0 1px transparent, 0 0 0 rgba(94, 242, 255, 0); }
}
@keyframes zoneSpecial {
  0% { box-shadow: inset 0 0 0 2px rgba(139, 123, 255, 0.9), 0 0 36px rgba(139, 123, 255, 0.7); }
  100% { box-shadow: inset 0 0 0 1px transparent, 0 0 0 transparent; }
}
@keyframes zoneSet {
  0% { box-shadow: inset 0 0 0 2px rgba(255, 209, 102, 0.8), 0 0 24px rgba(255, 209, 102, 0.55); }
  100% { box-shadow: inset 0 0 0 1px transparent, 0 0 0 transparent; }
}
@keyframes zoneTrap {
  0% { box-shadow: inset 0 0 0 2px rgba(193, 97, 255, 0.9), 0 0 28px rgba(193, 97, 255, 0.6); }
  100% { box-shadow: inset 0 0 0 1px transparent, 0 0 0 transparent; }
}
@keyframes burstOut {
  0% { opacity: 1; transform-origin: left center; width: 8px; }
  100% { opacity: 0; width: 46px; transform: translateX(18px) rotate(var(--rot, 0deg)); }
}
@keyframes flashFade {
  0% { opacity: 0; }
  14% { opacity: 1; }
  100% { opacity: 0; }
}
@keyframes appShake {
  10%, 90% { transform: translate3d(-1px, 0, 0); }
  20%, 80% { transform: translate3d(2px, 0, 0); }
  30%, 50%, 70% { transform: translate3d(-3px, 0, 0); }
  40%, 60% { transform: translate3d(3px, 0, 0); }
}

/* skeleton */
.skeleton-track { height: 5px; margin-top: 8px; }
.skeleton-track i { display: block; width: 45%; height: 100%; background: rgba(94, 242, 255, 0.2); animation: dotPulse 1.4s infinite; }
.skeleton-grid { grid-template-columns: repeat(5, var(--card-w)); opacity: 0.5; }
.zone-skeleton { background: rgba(255, 255, 255, 0.02); animation: dotPulse 1.6s infinite; animation-delay: calc(var(--i) * -0.12s); }

/* accessibility fallbacks */
@media (prefers-reduced-motion: reduce) {
  .card { animation-duration: 9s; }
  .card-sheen, .rarity-ur::after, .rarity-sr::after { animation-duration: 12s; }
  .orb { animation-duration: 30s; }
}

/* ============================================================
   DUEL 24 ZONES — drawers, overlays, modals, responsive
   ============================================================ */

/* ───────────────────────── drawer ───────────────────────── */

.drawer-scrim {
  position: fixed;
  inset: 0;
  z-index: 40;
  background: rgba(2, 4, 12, 0.62);
  backdrop-filter: blur(3px);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.25s;
}
body.drawer-open .drawer-scrim { opacity: 1; pointer-events: auto; }

.drawer {
  position: fixed;
  top: 0;
  right: 0;
  bottom: 0;
  z-index: 50;
  display: flex;
  flex-direction: column;
  width: min(410px, 95vw);
  border-left: 1px solid rgba(94, 242, 255, 0.22);
  background:
    linear-gradient(180deg, rgba(12, 18, 48, 0.97), rgba(5, 7, 22, 0.985)),
    #060818;
  box-shadow: -20px 0 60px rgba(0, 0, 0, 0.65);
  transform: translateX(104%);
  transition: transform 0.3s cubic-bezier(0.2, 0.8, 0.2, 1);
}
body.drawer-open .drawer { transform: translateX(0); }

.drawer-head {
  flex: 0 0 auto;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  padding: 16px 16px 12px;
  border-bottom: 1px solid var(--line);
  background: linear-gradient(180deg, rgba(94, 242, 255, 0.05), transparent);
}
.eyebrow {
  margin: 0 0 3px;
  font-family: var(--font-mono);
  font-size: 7px;
  letter-spacing: 0.24em;
  color: var(--cyan);
  opacity: 0.85;
}
.drawer-head h2 {
  margin: 0;
  font-size: 16px;
  letter-spacing: 0.06em;
  font-weight: 800;
}
.x-btn {
  flex: 0 0 auto;
  width: 28px;
  height: 28px;
  border: 1px solid var(--line);
  border-radius: 6px;
  background: rgba(255, 255, 255, 0.03);
  color: var(--muted);
  font-size: 17px;
  line-height: 1;
  cursor: pointer;
  transition: all 0.18s;
}
.x-btn:hover { color: #fff; border-color: var(--red); }

.drawer-body {
  flex: 1 1 auto;
  overflow-y: auto;
  padding: 10px 14px 30px;
  display: flex;
  flex-direction: column;
  gap: 12px;
  scrollbar-width: thin;
  scrollbar-color: rgba(94, 242, 255, 0.25) transparent;
}
.drawer-body::-webkit-scrollbar { width: 4px; }
.drawer-body::-webkit-scrollbar-thumb { background: rgba(94, 242, 255, 0.22); border-radius: 99px; }

.drawer-section {
  padding: 10px;
  border: 1px solid var(--line);
  border-radius: 9px;
  background: rgba(8, 13, 34, 0.55);
}
.section-head {
  display: flex;
  align-items: center;
  gap: 7px;
  margin-bottom: 8px;
}
.section-head h3 {
  margin: 0;
  flex: 1 1 auto;
  font-size: 10px;
  letter-spacing: 0.1em;
  font-weight: 700;
  color: #dcecff;
}
.section-note {
  margin: -2px 0 8px;
  font-size: 8px;
  line-height: 1.45;
  color: var(--dim);
}
.badge {
  flex: 0 0 auto;
  padding: 2px 6px;
  border: 1px solid var(--line);
  border-radius: 3px;
  font-family: var(--font-mono);
  font-size: 6.5px;
  letter-spacing: 0.1em;
  color: var(--muted);
}
.badge-live { color: var(--green); border-color: rgba(93, 242, 160, 0.4); background: rgba(93, 242, 160, 0.08); }
.badge-away { color: var(--gold); border-color: rgba(255, 209, 102, 0.35); background: rgba(255, 209, 102, 0.07); }
.badge-full { color: var(--dim); }

.own-room { border-color: rgba(94, 242, 255, 0.28); background: linear-gradient(160deg, rgba(94, 242, 255, 0.055), rgba(8, 13, 34, 0.55) 62%); }
.own-code {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 7px 9px;
  border: 1px dashed rgba(94, 242, 255, 0.3);
  border-radius: 6px;
  background: rgba(94, 242, 255, 0.04);
}
.own-code > span {
  font-family: var(--font-mono);
  font-size: 6px;
  letter-spacing: 0.16em;
  color: var(--dim);
}
.own-code > b {
  font-family: var(--font-mono);
  font-size: 22px;
  letter-spacing: 0.18em;
  color: var(--cyan);
  text-shadow: 0 0 14px rgba(94, 242, 255, 0.45);
  line-height: 1;
}
.own-code .mini-btn { margin-left: auto; }
.own-meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin: 8px 0;
  font-family: var(--font-mono);
  font-size: 7px;
  color: var(--muted);
}
.room-status {
  font-family: var(--font-mono);
  font-size: 6.5px;
  letter-spacing: 0.06em;
  padding: 1px 5px;
  border-radius: 2px;
  border: 1px solid var(--line);
}
.room-status.cpu { color: var(--green); border-color: rgba(93, 242, 160, 0.3); }
.room-status.pvp { color: var(--magenta); border-color: rgba(255, 78, 205, 0.35); }
.room-status.away { color: var(--gold); border-color: rgba(255, 209, 102, 0.3); }
.room-actions { display: flex; flex-wrap: wrap; gap: 5px; margin-top: 8px; }
.room-note {
  margin: 8px 0 0;
  font-size: 7.5px;
  line-height: 1.5;
  color: var(--dim);
}

.mini-btn {
  padding: 4px 8px;
  border: 1px solid rgba(94, 242, 255, 0.3);
  border-radius: 4px;
  background: rgba(94, 242, 255, 0.06);
  color: #cdefff;
  font-family: var(--font-mono);
  font-size: 7px;
  letter-spacing: 0.1em;
  cursor: pointer;
  white-space: nowrap;
  transition: all 0.16s;
}
.mini-btn:hover:not(:disabled) { border-color: var(--cyan); background: rgba(94, 242, 255, 0.13); }
.mini-btn:disabled { opacity: 0.35; cursor: not-allowed; }
.mini-btn.join { border-color: rgba(255, 78, 205, 0.45); color: #ffd9f6; background: rgba(255, 78, 205, 0.1); }
.mini-btn.join:hover:not(:disabled) { border-color: var(--magenta); background: rgba(255, 78, 205, 0.2); }

.room-list { display: flex; flex-direction: column; gap: 5px; }
.room-row {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 7px 8px;
  border: 1px solid var(--line);
  border-radius: 6px;
  background: rgba(255, 255, 255, 0.018);
  transition: border-color 0.18s;
}
.room-row:hover { border-color: rgba(94, 242, 255, 0.3); }
.room-row.current { border-color: rgba(94, 242, 255, 0.4); background: rgba(94, 242, 255, 0.05); }
.room-row-main { flex: 1 1 auto; min-width: 0; }
.room-row-top { display: flex; align-items: center; gap: 6px; flex-wrap: wrap; }
.room-row-top b { font-size: 9px; color: #e8f4ff; max-width: 130px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.room-code {
  font-family: var(--font-mono);
  font-size: 8px;
  letter-spacing: 0.12em;
  color: var(--cyan);
  opacity: 0.85;
}
.room-row-sub { margin: 3px 0 0; font-family: var(--font-mono); font-size: 6px; color: var(--dim); letter-spacing: 0.04em; }

.empty-rooms {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  padding: 12px;
  border: 1px dashed var(--line);
  border-radius: 7px;
  text-align: center;
}
.empty-icon {
  display: grid;
  place-items: center;
  width: 34px;
  height: 34px;
  border: 1px solid rgba(94, 242, 255, 0.25);
  border-radius: 50%;
  font-family: var(--font-mono);
  font-size: 12px;
  color: var(--cyan);
}
.empty-rooms p { margin: 0; font-size: 8px; color: var(--dim); }

.name-form { display: flex; gap: 5px; }
.name-form input {
  flex: 1 1 auto;
  min-width: 0;
  height: 28px;
  padding: 0 8px;
  border: 1px solid var(--line);
  border-radius: 5px;
  background: rgba(3, 7, 20, 0.75);
  color: var(--ink);
  font-family: var(--font-mono);
  font-size: 9px;
  letter-spacing: 0.04em;
}
.name-form input:focus { border-color: var(--cyan); outline: none; box-shadow: 0 0 10px rgba(94, 242, 255, 0.15); }

.log-list {
  display: flex;
  flex-direction: column;
  gap: 3px;
  max-height: 170px;
  margin: 0;
  padding: 0;
  list-style: none;
  overflow-y: auto;
  scrollbar-width: thin;
  scrollbar-color: rgba(94, 242, 255, 0.2) transparent;
}
.log-list li {
  display: flex;
  gap: 6px;
  padding: 3px 5px;
  border-left: 2px solid rgba(94, 242, 255, 0.12);
  background: rgba(255, 255, 255, 0.02);
  font-size: 7.5px;
  line-height: 1.35;
  color: var(--muted);
}
.log-list li.tone-p0 { border-left-color: var(--cyan); }
.log-list li.tone-p1 { border-left-color: var(--magenta); }
.log-list li.tone-system { border-left-color: var(--gold); color: #b7c4e4; }
.log-turn {
  flex: 0 0 auto;
  font-family: var(--font-mono);
  font-size: 6px;
  color: var(--dim);
  padding-top: 1px;
}

.rules-section details { border: 0; }
.rules-section summary {
  cursor: pointer;
  font-size: 9px;
  letter-spacing: 0.08em;
  color: #cfe4ff;
  padding: 2px 0;
  list-style: none;
}
.rules-section summary::-webkit-details-marker { display: none; }
.rules-section summary::before { content: "▸ "; color: var(--cyan); }
.rules-section details[open] summary::before { content: "▾ "; }
.rules-section ul {
  margin: 7px 0 0;
  padding: 0 0 0 14px;
  display: flex;
  flex-direction: column;
  gap: 4px;
  font-size: 7.5px;
  line-height: 1.5;
  color: var(--muted);
}
.rules-section li::marker { color: var(--cyan); }
.rules-section b { color: var(--ink); }
.surrender { margin-top: 10px; width: 100%; }
.no-image {
  margin: 12px 0 0;
  font-family: var(--font-mono);
  font-size: 5.5px;
  letter-spacing: 0.14em;
  text-align: center;
  color: var(--dim);
  opacity: 0.7;
}
.current-room { border-color: rgba(255, 78, 205, 0.25); }

/* ───────────────────────── overlay ───────────────────────── */

.overlay {
  position: fixed;
  inset: 0;
  z-index: 70;
  display: none;
  align-items: center;
  justify-content: center;
  padding: 18px;
  background: rgba(3, 5, 16, 0.68);
  backdrop-filter: blur(7px);
}
.overlay.show { display: flex; animation: overlayIn 0.3s ease-out; }

.overlay-panel {
  position: relative;
  width: min(520px, 94vw);
  padding: 26px 26px 22px;
  border: 1px solid rgba(94, 242, 255, 0.3);
  border-radius: 14px;
  background:
    linear-gradient(160deg, rgba(94, 242, 255, 0.07), transparent 48%),
    linear-gradient(180deg, rgba(13, 20, 52, 0.98), rgba(5, 7, 22, 0.99));
  box-shadow: 0 30px 90px rgba(0, 0, 0, 0.75), 0 0 60px rgba(94, 242, 255, 0.08);
  overflow: hidden;
  text-align: center;
}
.overlay-panel::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: 14px;
  padding: 1px;
  background: linear-gradient(135deg, rgba(94, 242, 255, 0.6), transparent 35%, transparent 65%, rgba(255, 78, 205, 0.5));
  -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
  -webkit-mask-composite: xor;
  mask-composite: exclude;
  pointer-events: none;
}
.overlay-copy {
  margin: 8px auto 16px;
  max-width: 380px;
  font-size: 10px;
  line-height: 1.6;
  color: var(--muted);
}
.connect-panel h2, .gone-panel h2 {
  margin: 4px 0 0;
  font-family: var(--font-display);
  font-size: clamp(20px, 3vw, 30px);
  letter-spacing: 0.06em;
  font-weight: 900;
}
.gone-panel h2 { color: var(--red); }

.spinner {
  width: 44px;
  height: 44px;
  margin: 0 auto 14px;
  border-radius: 50%;
  border: 2px solid rgba(94, 242, 255, 0.14);
  border-top-color: var(--cyan);
  border-right-color: var(--magenta);
  animation: spinSlow 0.9s linear infinite;
  box-shadow: 0 0 24px rgba(94, 242, 255, 0.2);
}

.result-panel { text-align: left; padding-top: 30px; }
.result-rays {
  position: absolute;
  left: 50%;
  top: -40%;
  width: 140%;
  height: 140%;
  transform: translateX(-50%);
  background:
    conic-gradient(from 0deg, transparent 0 8%, rgba(255, 209, 102, 0.08) 9%, transparent 10% 18%, rgba(94, 242, 255, 0.07) 19%, transparent 20% 100%);
  animation: spinSlow 26s linear infinite;
  pointer-events: none;
}
.result-win .result-rays { opacity: 1; }
.result-lose .result-rays { filter: hue-rotate(160deg); opacity: 0.6; }
.result-title {
  position: relative;
  margin: 4px 0 2px;
  font-family: var(--font-display);
  font-size: clamp(38px, 7vw, 68px);
  line-height: 1;
  letter-spacing: 0.04em;
  font-weight: 900;
}
.result-win .result-title {
  background: linear-gradient(180deg, #fff7d6, var(--gold) 45%, #ff9f43 75%, #ff4ecd);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  filter: drop-shadow(0 0 24px rgba(255, 209, 102, 0.4));
}
.result-lose .result-title {
  background: linear-gradient(180deg, #ffd9e0, var(--red) 55%, #8b7bff);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  filter: drop-shadow(0 0 24px rgba(255, 85, 112, 0.35));
}
.result-reason {
  position: relative;
  margin: 0 0 14px;
  font-family: var(--font-mono);
  font-size: 8px;
  letter-spacing: 0.12em;
  color: var(--muted);
}
.result-stats {
  position: relative;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 6px;
  margin: 12px 0 16px;
}
.result-stats div {
  padding: 8px 6px;
  border: 1px solid var(--line);
  border-radius: 7px;
  background: rgba(255, 255, 255, 0.025);
}
.result-stats span {
  display: block;
  font-family: var(--font-mono);
  font-size: 5.5px;
  letter-spacing: 0.12em;
  color: var(--dim);
  margin-bottom: 3px;
}
.result-stats b {
  font-family: var(--font-mono);
  font-size: clamp(13px, 1.8vw, 19px);
  color: var(--ink);
  font-variant-numeric: tabular-nums;
}
.result-actions {
  position: relative;
  display: flex;
  gap: 7px;
  justify-content: flex-start;
}
.result-note {
  position: relative;
  margin: 11px 0 0;
  font-size: 7.5px;
