/* ───────────────────────── modal ───────────────────────── */

.modal {
  position: fixed;
  inset: 0;
  z-index: 80;
  display: none;
  align-items: center;
  justify-content: center;
  padding: 16px;
}
.modal.show { display: flex; }
.modal-back {
  position: absolute;
  inset: 0;
  background: rgba(3, 5, 16, 0.72);
  backdrop-filter: blur(4px);
}
.modal-panel {
  position: relative;
  width: min(700px, 95vw);
  max-height: 84dvh;
  display: flex;
  flex-direction: column;
  border: 1px solid rgba(94, 242, 255, 0.28);
  border-radius: 12px;
  background: linear-gradient(180deg, rgba(13, 20, 52, 0.99), rgba(5, 7, 22, 0.995));
  box-shadow: 0 30px 90px rgba(0, 0, 0, 0.8);
  animation: modalIn 0.24s cubic-bezier(0.2, 0.9, 0.2, 1);
  overflow: hidden;
}
.modal-head {
  flex: 0 0 auto;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  padding: 14px 16px 11px;
  border-bottom: 1px solid var(--line);
  background: linear-gradient(180deg, rgba(94, 242, 255, 0.05), transparent);
}
.modal-head h2 { margin: 0; font-size: 14px; letter-spacing: 0.04em; }
.modal-cards {
  flex: 1 1 auto;
  overflow-y: auto;
  padding: 10px;
  display: flex;
  flex-direction: column;
  gap: 6px;
  scrollbar-width: thin;
  scrollbar-color: rgba(94, 242, 255, 0.22) transparent;
}
.card-row {
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 8px 9px;
  border: 1px solid var(--line);
  border-left: 3px solid rgba(94, 242, 255, 0.3);
  border-radius: 6px;
  background: rgba(255, 255, 255, 0.02);
}
.card-row.attr-light { border-left-color: var(--gold); }
.card-row.attr-dark { border-left-color: var(--violet); }
.card-row.attr-fire { border-left-color: #ff8a5c; }
.card-row.attr-wind { border-left-color: #6dffb0; }
.card-row.attr-earth { border-left-color: #c99a5f; }
.card-row.attr-spell { border-left-color: #24d6ad; }
.card-row.attr-trap { border-left-color: #c161ff; }
.row-glyph {
  flex: 0 0 auto;
  display: grid;
  place-items: center;
  width: 34px;
  height: 34px;
  border: 1px solid var(--line);
  border-radius: 6px;
  background: radial-gradient(circle, rgba(94, 242, 255, 0.18), rgba(5, 8, 22, 0.9));
  font-size: 16px;
  font-weight: 800;
}
.row-main { flex: 1 1 auto; min-width: 0; }
.row-title { display: flex; align-items: center; gap: 6px; flex-wrap: wrap; }
.row-title b { font-size: 10px; color: #f0f8ff; }
.row-stat { font-family: var(--font-mono); font-size: 6.5px; color: var(--dim); }
.row-text { margin: 2px 0 0; font-size: 7.5px; line-height: 1.4; color: var(--muted); }
.pile-empty-view { text-align: center; padding: 24px 16px; }
.big-pile {
  display: block;
  font-family: var(--font-mono);
  font-size: 48px;
  color: var(--cyan);
  text-shadow: 0 0 26px rgba(94, 242, 255, 0.35);
  line-height: 1;
}
.pile-empty-view p { margin: 8px 0 0; font-size: 9px; color: var(--muted); }
.pile-empty { padding: 24px; text-align: center; font-size: 9px; color: var(--dim); }

/* ───────────────────────── toast ───────────────────────── */

.toast {
  position: fixed;
  left: 50%;
  bottom: max(18px, env(safe-area-inset-bottom));
  z-index: 100;
  transform: translate(-50%, 20px);
  max-width: min(90vw, 540px);
  padding: 9px 15px;
  border: 1px solid rgba(94, 242, 255, 0.3);
  border-radius: 7px;
  background: rgba(8, 13, 34, 0.96);
  box-shadow: 0 10px 35px rgba(0, 0, 0, 0.65), 0 0 24px rgba(94, 242, 255, 0.12);
  font-size: 9px;
  line-height: 1.45;
  color: #dff3ff;
  text-align: center;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.22s, transform 0.22s;
}
.toast.show { opacity: 1; transform: translate(-50%, 0); }
.toast.tone-warn { border-color: rgba(255, 85, 112, 0.5); color: #ffe0e6; }
.toast.tone-pvp { border-color: rgba(255, 78, 205, 0.5); color: #ffe1f8; }
.toast.tone-info { border-color: rgba(94, 242, 255, 0.4); }

.noscript {
  position: fixed;
  inset: 0;
  z-index: 200;
