cd /home/runner/work/PlayGround/PlayGround && cat > /tmp/sim.mjs <<'EOF'
import { createDuel, applyAction, aiChooseAction, canSpecialSummon } from './js/engine.js'
let wins = {0:0,1:0}, errors = []
for (let g = 0; g < 60; g++) {
  const st = createDuel(['P0','P1'], g % 2, {cpuOpponent:true, mode:'cpu'})
  let actions = 0
  while (st.winner == null && actions < 240) {
    const side = st.active
    const act = aiChooseAction(st, side)
    if (!act) { errors.push({g, msg:'no action', side, turn:st.turn, phase:st.phase}); break }
    const res = applyAction(st, side, act)
    if (!res.ok) { errors.push({g, msg:res.error, act, turn:st.turn, phase:st.phase}); break }
    actions++
  }
  if (st.winner != null) wins[st.winner]++; else errors.push({g,msg:'timeout',turn:st.turn,lp:st.players.map(p=>p.lp), hand:st.players.map(p=>p.hand.length)})
}
console.log('wins', wins, 'errors', errors.slice(0,8), 'errorCount', errors.length)
EOF
node --experimental-default-type=module /tmp/sim.mjs

