  if (action.type === 'surrender') {
    endDuel(st, 1 - side, '降参', ev)
    st.rev = (st.rev || 0) + 1
    return { ok: true, events: ev }
  }
  if (side !== st.active) return { ok: false, error: '相手のターン中です', events: ev }
  const p = st.players[side]
  const o = st.players[1 - side]
  let error = null

